# #797: XTTS is the box's single biggest tenant (~23G of unified memory).
# When nothing has asked it to render for a while, offload it — the #794
# ladder means every clone voice still airs (same reference through F5),
# and the first render that WANTS XTTS wakes it back up in the background.
_XTTS_LAST_USED = [time.time()]
_XTTS_REVIVE_AT = [0.0]
XTTS_IDLE_UNLOAD = float(os.getenv("XTTS_IDLE_UNLOAD", "1800"))  # 30 min

# #1060: measured host resources and bounded, owned recovery actions. Sampling
# runs outside the broadcast loop; reports never mistake queue latency for
# hardware throughput or GB10's unavailable dedicated-VRAM total for zero.
_RESOURCE_HISTORY = ResourceHistory(data_path("resource_history.json"))
_RESOURCE_STATE: dict[str, Any] = {}
_RESOURCE_PRESSURE_SAMPLES = [0]
_RESOURCE_RECLAIM_AT = [0.0]
_RESOURCE_COMFY_IDLE_SINCE = [0.0]
_RESOURCE_GATE = asyncio.Lock()


def resource_brief(since: float | None = None,
                   until: float | None = None) -> dict[str, Any]:
    """Current observation plus a compact summary of retained hour evidence.

    Sampling is intermittent and bounded, so even a covered retention window
    cannot establish continuous memory pressure or service health.
    """
    end = time.time() if until is None else float(until)
    start = float(since) if since is not None else None
    retained = [row for row in list(_RESOURCE_HISTORY.rows[-ResourceHistory.MAX_SAMPLES:])
                if isinstance(row, dict) and isinstance(row.get("at"), (int, float))
                and math.isfinite(row["at"])]
    rows = [row for row in retained if row["at"] <= end
            and (start is None or row["at"] >= start)]
    rows.sort(key=lambda row: row["at"])
    values = [value for row in rows
              if (value := available_gb(row.get("memory") or {})) is not None]
    tiers: dict[str, int] = {}
    reasons: dict[tuple[str, str], int] = {}
    actions = []
    for row in rows:
        decision = row.get("decision") or {}
        tier = str(decision.get("tier") or "unknown")
        tiers[tier] = tiers.get(tier, 0) + 1
        reason = str(decision.get("reason") or "")[:600]
        if reason:
            pair = (tier, reason)
            reasons[pair] = reasons.get(pair, 0) + 1
        action = row.get("action")
        if isinstance(action, dict):
            actions.append({"at": row["at"], "kind": action.get("kind"),
                            "ok": action.get("ok") if isinstance(action.get("ok"), bool) else None,
                            "why": str(action.get("why") or "")[:600], "reason": reason})
    oldest = min((row["at"] for row in retained), default=None)
    newest = max((row["at"] for row in retained), default=None)
    coverage = ("no observations in requested interval" if not rows else
                "requested start precedes retained observations" if start is not None
                and oldest is not None and start < oldest else "retained observations in requested interval")
    summary = {
        "since": start, "until": end, "samples": len(rows),
        "memory_samples": len(values), "missing_memory_samples": len(rows) - len(values),
        "available_gb": {"min": min(values) if values else None,
                         "max": max(values) if values else None},
        "tier_counts": tiers, "action_count": len(actions), "actions": actions[-20:],
        "reason_count": len(reasons),
        "reasons": [{"tier": tier, "reason": reason, "samples": count}
                    for (tier, reason), count in list(reasons.items())[-20:]],
        "detail_limit": 20,
        "retention": {"sample_limit": ResourceHistory.MAX_SAMPLES,
                      "retained_samples": len(retained), "oldest_at": oldest, "newest_at": newest,
                      "first_in_interval": rows[0]["at"] if rows else None,
                      "last_in_interval": rows[-1]["at"] if rows else None,
                      "coverage": coverage,
                      "note": "Intermittent samples; gaps and periods outside retention are unobserved."},
    }
    return {**{key: _RESOURCE_STATE.get(key) for key in (
                "at", "memory", "gpu", "decision", "models", "comfy",
                "engines_last_render_seconds", "writing", "booths")},
            "recent": list(_RESOURCE_HISTORY.rows[-3:]), "history": summary}


def resource_engine_protected(engine: str, *, keep_cast: bool = True) -> bool:
    if engine_busy(engine, recording_booths()):
        return True
    return bool(keep_cast and _RADIO.get("on") and engine == host_clone_engine())


async def resource_sample() -> dict[str, Any]:
    async with _RESOURCE_GATE:
        async with httpx.AsyncClient(timeout=5) as client:
            async def read(url: str) -> dict[str, Any]:
                try:
                    response = await client.get(url)
                    response.raise_for_status()
                    value = response.json()
                    return value if isinstance(value, dict) else {}
                except Exception:
                    return {}
            memory, gpu, pressure, models, queue = await asyncio.gather(
                asyncio.to_thread(memory_snapshot),
                asyncio.to_thread(gpu_snapshot),
                read(f"{VOICE_DIRECTOR_URL}/host/pressure"),
                read(f"{OLLAMA_URL}/api/ps"), read(f"{COMFYUI_URL}/queue"))
        if available_gb(memory) is None and available_gb(pressure) is not None:
            memory = {"avail_gb": available_gb(pressure), "source": "voice director host pressure"}
        now = time.time()
        booths, writing = recording_booths(), writing_room_state()
        owned = set(radio_owned_models())
        comfy_observed = "queue_running" in queue and "queue_pending" in queue
        comfy_busy = bool(queue.get("queue_running") or queue.get("queue_pending"))
        if not comfy_observed or comfy_busy:
            _RESOURCE_COMFY_IDLE_SINCE[0] = 0.0
        elif not _RESOURCE_COMFY_IDLE_SINCE[0]:
            _RESOURCE_COMFY_IDLE_SINCE[0] = now
        comfy_idle_since = max(_RESOURCE_COMFY_IDLE_SINCE[0] or now, _COMFY_LAST_USED[0])
        snapshot = {"at": now, "memory": memory, "gpu": gpu,
                    "booths": booths, "writing": writing,
                    "engines_last_render_seconds": pressure.get("engine_last_render") or {},
                    "models": [{"name": row.get("name"), "bytes": row.get("size"),
                                "gpu_bytes": row.get("size_vram"),
                                "station_owned": row.get("name") in owned,
                                "busy": any(job.get("model") == row.get("name")
                                            for job in writing.get("jobs", []))}
                               for row in models.get("models", [])],
                    "comfy": {"observed": comfy_observed, "busy": comfy_busy,
                              "idle_seconds": max(0, now - comfy_idle_since)}}
        available = available_gb(memory)
        _RESOURCE_PRESSURE_SAMPLES[0] = (_RESOURCE_PRESSURE_SAMPLES[0] + 1
                                         if available is not None and available < 24 else 0)
        decision = assess_resources(snapshot, _RESOURCE_PRESSURE_SAMPLES[0])
        action = None
        if decision["actions"] and now - _RESOURCE_RECLAIM_AT[0] >= 600:
            # Only this allowlisted cache operation is automatic. Recheck the
            # queue immediately before freeing; never terminate the service.
            _RESOURCE_RECLAIM_AT[0] = now
            action = {"kind": "free_comfy_cache", "ok": False}
            try:
                async with httpx.AsyncClient(timeout=10) as client:
                    response = await client.get(f"{COMFYUI_URL}/queue")
                    response.raise_for_status()
                    fresh = response.json()
                    if ("queue_running" in fresh and "queue_pending" in fresh
                            and not fresh["queue_running"] and not fresh["queue_pending"]
                            and time.time() - max(_COMFY_LAST_USED[0],
                                _RESOURCE_COMFY_IDLE_SINCE[0] or time.time()) >= 300):
                        response = await client.post(f"{COMFYUI_URL}/free",
                            json={"unload_models": True, "free_memory": True})
                        response.raise_for_status()
                        action["ok"] = True
                    else:
                        _RESOURCE_COMFY_IDLE_SINCE[0] = 0.0
                        action["why"] = "Image work appeared during the recheck; kept the cache."
            except Exception as exc:
                action["why"] = type(exc).__name__
        snapshot["decision"] = decision
        _RESOURCE_STATE.clear()
        _RESOURCE_STATE.update(snapshot)
        await asyncio.to_thread(_RESOURCE_HISTORY.record, snapshot, decision, action)
        if action:
            station_flow_event("resources", "ok" if action["ok"] else "wait",
                               decision["reason"], {"resource_action": action, "memory": memory})
        return snapshot


async def resource_clock() -> None:
    await asyncio.sleep(12)
    while True:
        try:
            await resource_sample()
            if _XTTS_FAILS:
                await _xtts_bounce_maybe(observe_failure=False)
        except Exception as exc:
            _RESOURCE_STATE["observation_error"] = type(exc).__name__
        await asyncio.sleep(45)


@app.on_event("startup")
async def _startup_resource_guard() -> None:
    fire_and_forget(resource_clock())


LIFEBOAT_URL = os.getenv("LIFEBOAT_URL", "http://127.0.0.1:8099")
_XTTS_FAILS: list[float] = []
_XTTS_BOUNCE_AT = [0.0]
_XTTS_BOUNCE_PENDING = [""]              # "terminate" or "deploy" until repaired
_XTTS_BOUNCE_GATE = asyncio.Lock()


async def _lifeboat_restart(service: str) -> bool:
    """#825: the hand OUTSIDE the water — when the voice-director itself
    is the casualty, the lifeboat (systemd, outside docker) restarts it
    so every engine handle comes back."""
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            r = await client.post(
                f"{LIFEBOAT_URL}/restart/{service}",
                headers={"X-Lifeboat-Key":
                         os.getenv("SPARK_AGENT_API_KEY", "")})
        ok = r.status_code < 300
        pipeline_log("repair", f"lifeboat restart {service}: "
                     + ("ok" if ok else str(r.status_code)) + " (#825)")
        return ok
    except Exception as exc:  # noqa: BLE001
        pipeline_log("repair", f"lifeboat unreachable: {exc} (#825)")
        return False


async def _director_post(path: str) -> bool:
    """#825: a director call that HEALS the director — if :8090 does not
    answer, the lifeboat restarts it and the call retries once. The DJs
    never lose their engine handles to a dead middleman."""
    engine = path.split("/")[-2] if path.endswith("/terminate") else ""
    for attempt in (0, 1):
        # The first request or the director's restart may yield long enough
        # for a recording to begin. Every destructive attempt checks anew.
        if engine and resource_engine_protected(engine, keep_cast=False):
            return False
        try:
            async with httpx.AsyncClient(timeout=45) as client:
                response = await client.post(f"{VOICE_DIRECTOR_URL}{path}")
                response.raise_for_status()
            return True
        except httpx.HTTPStatusError:
            return False                 # a live director rejecting a call is not dead
        except Exception:  # noqa: BLE001
            if attempt:
                return False
            if engine and resource_engine_protected(engine, keep_cast=False):
                return False
            booths = recording_booths()
            if (booths.get("live") or booths.get("preparing")
                    or any((booths.get("engines") or {}).values())):
                return False            # restarting the director affects every engine
            if not await _lifeboat_restart("voice-director"):
                return False
            await asyncio.sleep(6)
    return False


async def _xtts_bounce_maybe(*, observe_failure: bool = True) -> None:
    """#825: an XTTS that answers /health but fails renders is WEDGED —
    three failures inside ten minutes gets it terminated and redeployed
    (15-minute cooldown), because a wedge never fixes itself."""
    now = time.time()
    if observe_failure:
        _XTTS_FAILS.append(now)
    del _XTTS_FAILS[:-8]
    recent = [t for t in _XTTS_FAILS if now - t < 600]
    if len(recent) >= 3 and not _XTTS_BOUNCE_PENDING[0]:
        _XTTS_BOUNCE_PENDING[0] = "terminate"
    if not _XTTS_BOUNCE_PENDING[0] or now - _XTTS_BOUNCE_AT[0] < 900:
        return
    async with _XTTS_BOUNCE_GATE:
        if not _XTTS_BOUNCE_PENDING[0] or time.time() - _XTTS_BOUNCE_AT[0] < 900:
            return
        if _XTTS_BOUNCE_PENDING[0] == "terminate":
            try:
                healthy = bool((await xtts_health()).get("ready"))
            except Exception:  # noqa: BLE001
                healthy = False
            if not healthy:
                return                  # dead, not wedged — revive owns it
            if resource_engine_protected("xtts", keep_cast=False):
                return                  # pending survives a long busy interval
            pipeline_log("repair", "XTTS answers health but failed 3 renders in "
                         "10 min — WEDGED; bouncing it through the director "
                         "(#825)")
            if not await _director_post("/director/engine/xtts/terminate"):
                return                  # refusal never spends evidence or cooldown
            _XTTS_BOUNCE_PENDING[0] = "deploy"
            await asyncio.sleep(3)
        if not await _director_post("/director/engine/xtts/deploy"):
            return                      # retry deployment without terminating again
        _XTTS_BOUNCE_PENDING[0] = ""
        _XTTS_FAILS.clear()
        _XTTS_BOUNCE_AT[0] = time.time()


def _xtts_revive_maybe() -> None:
    if time.time() - _XTTS_REVIVE_AT[0] < 600:
        return
    _XTTS_REVIVE_AT[0] = time.time()

    async def _up() -> None:
        try:
            async with httpx.AsyncClient(timeout=45) as client:
                # #812: make ROOM first. XTTS needs ~23G; under pressure
                # the deploy silently failed and F5 carried the whole
                # cast for hours — those were the underwater voices. The
                # small standin engines reload in seconds when wanted;
                # the primary voice engine outranks them.
                try:
                    press = (await client.get(
                        f"{VOICE_DIRECTOR_URL}/host/pressure")).json()
                    available = available_gb(press)
                    if available is not None and available < 26:
                        for spare in ("qwen_tts", "vibevoice", "cosyvoice",
                                      "voxcpm"):
                            if not resource_engine_protected(spare) and not engine_busy(
                                    spare, recording_booths(), press.get("engine_last_render")):
                                await _director_post(f"/director/engine/{spare}/terminate")
                    # #825: still cramped? The writer model steps out —
                    # it reloads on the next round write, and one slow
                    # round beats a cast with no voice.
                    try:
                        press2 = (await client.get(
                            f"{VOICE_DIRECTOR_URL}/host/pressure")).json()
                        available = available_gb(press2)
                        if available is not None and available < 30:
                            ps = (await client.get(
                                f"{OLLAMA_URL}/api/ps")
                            ).json() or {}
                            owned = set(radio_owned_models())
                            for m in ps.get("models", []):
                                name = str(m.get("name") or "")
                                # Shared embeddings, unknown tenants, active and
                                # queued writers are never an eviction candidate.
                                if name not in owned or _OLLAMA_JOBS:
                                    continue
                                response = await client.post(
                                    f"{OLLAMA_URL}/api/generate",
                                    json={"model": m.get("name"),
                                          "keep_alive": 0})
                                response.raise_for_status()
                                pipeline_log("gpu", f"Released idle station model {name} to fit XTTS (#1060)")
                    except Exception:  # noqa: BLE001
                        pass
                except Exception:  # noqa: BLE001
                    pass
                await client.post(
                    f"{VOICE_DIRECTOR_URL}/director/engine/xtts/deploy")
            pipeline_log("gpu", "XTTS was offloaded and is wanted again — "
                                "reloading it now; F5 carries the clones "
                                "until it answers (#797)")
        except Exception:  # noqa: BLE001
            pass
    fire_and_forget(_up())


async def one_engine_keeper() -> None:
    """#866: under the cast lock, exactly one cloning engine stays
    resident — the host's. The other is unloaded on sight.

    Not a memory nicety: with both loaded beside the writer, renders on
    this box went from ~9s to over 100s and the talk audibly gapped."""
    while True:
        await asyncio.sleep(180)
        try:
            if not cast_engine_locked():
                continue
            want = host_clone_engine()
            other = "f5" if want == "xtts" else "xtts"
            if resource_engine_protected(other):
                continue
            if not (await engine_health(other)).get("ready"):
                continue
            # Never leave the cast with nothing: only release the spare
            # once the engine we are keeping actually answers.
            if not (await engine_health(want)).get("ready"):
                continue
            if await _director_post(f"/director/engine/{other}/terminate"):
                pipeline_log("gpu", f"{other} was resident but the cast "
                             f"renders on {want} — released it so one "
                             "model has the box (#866)")
        except Exception:  # noqa: BLE001
            pass


@app.on_event("startup")
async def _startup_one_engine() -> None:
    fire_and_forget(one_engine_keeper())


async def xtts_idle_clock() -> None:
    while True:
        await asyncio.sleep(300)
        try:
            if XTTS_IDLE_UNLOAD <= 0:
                continue
            if time.time() - _XTTS_LAST_USED[0] < XTTS_IDLE_UNLOAD:
                continue
            if resource_engine_protected("xtts"):
                continue
            health = await engine_health("xtts")
            if not health.get("ready"):
                continue                 # already down or offloaded
            if not await _director_post("/director/engine/xtts/terminate"):
                continue
            pipeline_log("gpu", "nothing has asked XTTS to render in "
                         f"{int(XTTS_IDLE_UNLOAD // 60)} minutes — "
                         "offloaded (~23G back to the box); it reloads "
                         "the moment a render wants it (#797)")
        except Exception:  # noqa: BLE001
            pass


@app.on_event("startup")
async def _startup_xtts_idle() -> None:
    fire_and_forget(xtts_idle_clock())


@app.on_event("startup")
async def _startup_hold_watch() -> None:
    """The hold shelf drains for the LIFE of the app (#408, #409) — one
    watcher, started once, alive whether the show is on or off, so held
    dialogue reaches the box even between sessions. It used to be spawned
    per show-start: duplicates stacked across restarts and none existed
    off-air."""
    fire_and_forget(box_hold_watch())


async def announce_render_complete() -> None:
    """Speak one of the user's configured completion replies (control panel →
    Render replies) through the voice pipe when an image lands. A nicety —
    it must never fail the tracker, and it stays silent when voice out
    (HA_TOKEN) isn't configured or the reply list is empty."""
    try:
        replies = load_settings().get("render_replies") or []
        if replies and _ha_creds()[0]:
            await speak(random.choice(replies), event="render")
    except Exception:
        pass


# --- Pine Box inbox (pine_requests.md) --------------------------------------
# Requests submitted from any computer are PREPENDED here as markdown blocks,
# resolved behind the scenes, then removed. The .md is the canonical store so
# it is human- and Claude-readable/editable directly.

_pine_lock = asyncio.Lock()
_PINE_CONVERSATIONS: dict[str, float] = {}
PINE_CONVERSATION_SECONDS = 600.0
PINE_REQUEST_QUESTION = "What would you like to say for your Pine Box request?"
_PINE_REQUEST_COMMAND = re.compile(
    r"^(?:(?:hey[, ]+)?(?:pine\s*box[, ]+)?|please\s+)?"
    r"(?:(?:i(?:'d| would| want to| would like to)|can (?:i|you)|"
    r"could (?:i|you)|let me|help me)\s+)?"
    r"(?:like to\s+)?(?:file|submit|make|create|send|add)\s+"
    r"(?:a\s+|an? new\s+|the\s+)?pine\s*box\s+request"
    r"(?:\s*(?:[:\-]|saying\b|that\s+says\b)\s*(?P<body>.+)|[.!?\s]*)$",
    re.I | re.S,
)


async def pine_conversation(messages: list[dict[str, Any]],
                            session: str = "") -> dict[str, Any] | None:
    """#1053: a request is collected by this conversation, never the model.

    Full chat clients carry the question in their history. Voice clients may
    send one turn at a time, so their scoped session holds the question for
    ten minutes. No unscoped process-wide pending request can swallow another
    listener's next sentence.
    """
    text = latest_user_text(messages).strip()
    if not text:
        return None
    now = time.time()
    for old, until in list(_PINE_CONVERSATIONS.items()):
        if until < now:
            _PINE_CONVERSATIONS.pop(old, None)
    last_user = max((i for i, m in enumerate(messages)
                     if m.get("role") == "user"), default=-1)
    previous = next((m for m in reversed(messages[:last_user])
                     if m.get("role") in ("assistant", "user")), {})
    pending = (previous.get("role") == "assistant"
               and str(previous.get("content") or "").strip()
               == PINE_REQUEST_QUESTION)
    pending = pending or bool(session and session in _PINE_CONVERSATIONS)
    command = _PINE_REQUEST_COMMAND.fullmatch(text)
    body = str(command.group("body") or "").strip() if command else ""
    if command and not body:
        if session:
            _PINE_CONVERSATIONS[session] = now + PINE_CONVERSATION_SECONDS
        return {"reply": PINE_REQUEST_QUESTION, "state": "awaiting_request"}
    if not command and not pending:
        return None
    if pending and re.fullmatch(r"(?:cancel|never mind|nevermind|forget it|stop)[.!\s]*",
                                text, re.I):
        _PINE_CONVERSATIONS.pop(session, None)
        return {"reply": "Cancelled. No Pine Box request was filed.",
                "state": "cancelled"}
    item = await pine_append(body or text)
    _PINE_CONVERSATIONS.pop(session, None)
    return {"reply": f"Filed Pine Box request #{item['id']} in the inbox.",
            "state": "submitted", "submitted": item}


def pine_conversation_session(request: Request, payload: dict[str, Any]) -> str:
    """Use the client's conversation identity; keep single-turn voice scoped."""
    identity = (payload.get("conversation_id") or payload.get("chat_id")
                or payload.get("session_id") or payload.get("user"))
    client = request.client.host if request.client else "local"
    agent = str(request.headers.get("user-agent") or "")[:200]
    raw = f"{client}|{agent}|{str(identity or '')[:256]}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


# A request block: "## #<id> — <when> — <status>\n<body>" up to the next block.
_PINE_BLOCK_RE = re.compile(
    r"^## #(\d+) — (.*?) — (\w+)\n(.*?)(?=\n## #|\Z)",
    re.DOTALL | re.MULTILINE,
)


def _pine_next_id() -> int:
    try:
        n = int(PINE_SEQ_PATH.read_text().strip())
    except Exception:
        n = 0
    n += 1
    try:
        PINE_SEQ_PATH.parent.mkdir(parents=True, exist_ok=True)
        PINE_SEQ_PATH.write_text(str(n))
    except Exception:
        pass
    return n


def pine_read() -> list[dict[str, Any]]:
    try:
        text = PINE_REQUESTS_PATH.read_text(encoding="utf-8")
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for m in _PINE_BLOCK_RE.finditer(text):
        out.append({
            "id": int(m.group(1)),
            "when": m.group(2).strip(),
            "status": m.group(3).strip(),
            "text": m.group(4).strip(),
        })
    return out


def _pine_render(items: list[dict[str, Any]]) -> str:
    header = (
        "<!-- Pine Box inbox · newest first · resolved requests are "
        "removed. Submit from the Pine Chat panel on any computer. -->\n\n"
    )
    blocks = [
        f"## #{it['id']} — {it['when']} — {it['status']}\n{it['text']}\n"
        for it in items
    ]
    return header + "\n".join(blocks) + ("\n" if blocks else "")


# #1007: the body of a request WITHOUT its attachment blocks, which is
# what makes two submissions "the same request" even when they carry
# different screenshots.
_PINE_ATTACH_RE = re.compile(
    r"\n\nAttached (?:images|files):\n.*\Z", re.S)
PINE_SAME_WINDOW = 1800.0               # half an hour


def _pine_gist(text: str) -> str:
    body = _PINE_ATTACH_RE.sub("", str(text or "")).strip()
    return " ".join(body.lower().split())


def _pine_attachments(text: str) -> str:
    hit = _PINE_ATTACH_RE.search(str(text or ""))
    return hit.group(0) if hit else ""


async def pine_append(text: str) -> dict[str, Any]:
    """#1007: A REPEAT JOINS THE REQUEST IT REPEATS.

    The inbox was collecting the same ask several times over. Two roads
    led there and neither is a bug in the sending: a double-click on Send
    while the first POST is still in flight, and - the one that actually
    happened - an operator with four screenshots to attach, pasting and
    sending one at a time. Four requests, one sentence, one picture each:
    #980, #981, #982 and #983 are the same paragraph four times.

    Both are the same thing to a reader of the inbox: ONE request. So a
    submission whose words match an open request from the last half hour
    is folded into it, and its attachments are added to that request
    rather than starting another. Nothing is dropped - the screenshots
    all arrive, on the one item they belong to.

    Only OPEN requests are joined: re-asking for something already
    resolved is a new request, which is exactly what it means."""
    gist = _pine_gist(text)
    if gist:
        async with _pine_lock:
            items = pine_read()
            now = time.time()
            for it in items:
                if str(it.get("status") or "") != "open":
                    continue
                if _pine_gist(it.get("text") or "") != gist:
                    continue
                try:
                    when = time.mktime(time.strptime(
                        str(it.get("when") or ""), "%Y-%m-%d %H:%M"))
                except Exception:  # noqa: BLE001
                    when = now
                if now - when > PINE_SAME_WINDOW:
                    continue
                add = _pine_attachments(text)
                if add and add not in str(it.get("text") or ""):
                    it["text"] = (str(it.get("text") or "").rstrip()
                                  + add).strip()
                    PINE_REQUESTS_PATH.write_text(_pine_render(items), encoding="utf-8")
                return it
    async with _pine_lock:
        items = pine_read()
        item = {
            "id": _pine_next_id(),
            "when": time.strftime("%Y-%m-%d %H:%M"),
            "status": "open",
            # ponytail: a body line starting with "## #" could confuse the
            # parser; strip the marker if a user pastes one.
            "text": re.sub(r"(?m)^## #", "##_#", text.strip()),
        }
        items.insert(0, item)          # newest first
        PINE_REQUESTS_PATH.parent.mkdir(parents=True, exist_ok=True)
        PINE_REQUESTS_PATH.write_text(_pine_render(items), encoding="utf-8")
        return item


async def pine_remove(req_id: int) -> dict[str, Any] | None:
    async with _pine_lock:
        items = pine_read()
        found = None
        rest = []
        for it in items:
            if it["id"] == req_id and found is None:
                found = it
            else:
                rest.append(it)
        if found is not None:
            PINE_REQUESTS_PATH.write_text(_pine_render(rest), encoding="utf-8")
        return found


async def pine_complete(req_id: int, reply: str) -> dict[str, Any] | None:
    """Preserve the original request and verified result before clearing it."""
    async with _pine_lock:
        items = pine_read()
        item = next((row for row in items if row["id"] == req_id), None)
        if item is None:
            return None
        try:
            history = PINE_COMPLETED_PATH.read_text(encoding="utf-8")
        except FileNotFoundError:
            history = "<!-- Pine Box completed requests and verification. -->\n\n"
        heading = f"## #{req_id} — {time.strftime('%Y-%m-%d %H:%M')} — resolved"
        block = (f"{heading}\nSubmitted: {item['when']}\n\n{item['text']}\n\n"
                 f"Resolution: {reply.strip() or '(resolved)'}\n\n")
        # A failed inbox write can be retried without duplicating its archive.
        if not re.search(rf"(?m)^## #{req_id} — .* — resolved$", history):
            first, separator, tail = history.partition("\n\n")
            PINE_COMPLETED_PATH.parent.mkdir(parents=True, exist_ok=True)
            temp = PINE_COMPLETED_PATH.with_suffix(".tmp")
            temp.write_text(first + "\n\n" + block + tail, encoding="utf-8")
            temp.replace(PINE_COMPLETED_PATH)
        temp = PINE_REQUESTS_PATH.with_suffix(".tmp")
        temp.write_text(_pine_render([row for row in items if row["id"] != req_id]), encoding="utf-8")
        temp.replace(PINE_REQUESTS_PATH)
        return item


# --- #1079: THE REQUEST BOOK -------------------------------------------------
# "For every request that I make and you reply to it, I want you to store
#  that in a markdown that's able to be scrolled through through a page
#  viewer ... along with the token costs in and out for it."
#
# One markdown page per resolved request under data/pine_journal/<id>.md,
# with a sidecar <id>.json the viewer reads (the request, the reply, the
# costs and a flow chart drawn from the reply's own sections and steps).
# The book is backfilled once from pine_completed.md, so every request the
# archive remembers has a page, and the resolve door writes the next one.
#
# Costs, honestly: the request and the reply are counted at four characters
# per token (no tokenizer for the resolver's model exists here). The
# station's own model calls inside the request's window ride along from
# model_calls.jsonl, labelled as what they are - the writers and tints the
# station ran while the request was open - not the resolver's spend.
PINE_JOURNAL_DIR = data_path("pine_journal")
_PINE_JOURNAL_BACKFILLED = [False]
_PINE_COMPLETED_BLOCK_RE = re.compile(
    r"(?ms)^## #(\d+) — (.+?) — resolved\nSubmitted: (.*?)\n\n(.*?)\n\n"
    r"Resolution: (.*?)(?=\n## #\d+ — |\Z)")


def _pine_when_epoch(when: str) -> float:
    text = str(when or "").strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return float(time.mktime(time.strptime(text[:19] if "S" in fmt else text[:16], fmt)))
        except Exception:  # noqa: BLE001
            continue
    return 0.0


def _pine_tokens(text: str) -> int:
    return (len(str(text or "")) + 3) // 4


def _pine_request_images(text: str) -> list[str]:
    seen: list[str] = []
    for url in re.findall(r"/api/pine-uploads/[A-Za-z0-9._\-]+", str(text or "")):
        if url not in seen:
            seen.append(url)
    return seen


def pine_journal_graph(req_id: int, request: str, reply: str) -> dict[str, Any]:
    """The reply as a flow: the request at the root, its headings as
    sections, its bullets and numbered steps under the section they sit in.
    A reply with no headings gets its paragraphs as the sections."""
    request = str(request or "")
    nodes: list[dict[str, Any]] = [{"id": "n0", "label": f"Request #{req_id}",
                                    "kind": "request",
                                    "detail": " ".join(request.split())[:400]}]
    edges: list[dict[str, str]] = []
    section = "n0"
    headed = False
    in_code = False
    for raw in str(reply or "").splitlines():
        line = raw.strip()
        if line.startswith("```"):
            in_code = not in_code
            continue
        if in_code or not line or len(nodes) >= 90:
            continue
        head = re.match(r"^(#{1,6})\s+(.*)", line)
        if head:
            nid = f"n{len(nodes)}"
            title = head.group(2).strip().strip("#").strip()
            nodes.append({"id": nid, "label": title[:64], "kind": "section",
                          "detail": title[:300]})
            edges.append({"from": "n0", "to": nid})
            section = nid
            headed = True
            continue
        step = re.match(r"^(?:[-*•]|\d+[.)])\s+(.*)", line)
        if step:
            nid = f"n{len(nodes)}"
            body = step.group(1).strip()
            nodes.append({"id": nid, "label": re.sub(r"[*_`]", "", body)[:56],
                          "kind": "step", "detail": body[:500]})
            edges.append({"from": section, "to": nid})
            continue
        if not headed and len(line) > 24:
            nid = f"n{len(nodes)}"
            nodes.append({"id": nid, "label": re.sub(r"[*_`]", "", line)[:56],
                          "kind": "section", "detail": line[:500]})
            edges.append({"from": "n0", "to": nid})
            section = nid
    return {"nodes": nodes, "edges": edges}


def pine_journal_costs(request: str, reply: str, submitted: float,
                       resolved: float, rows: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    costs: dict[str, Any] = {"tokens_in": _pine_tokens(request), "tokens_out": _pine_tokens(reply),
                             "elapsed_s": int(max(0.0, resolved - submitted)) if submitted and resolved else 0,
                             "model_calls": 0, "model_seconds": 0.0, "model_tokens_out": 0,
                             "model_tokens_in": 0,
                             "note": ("token counts are estimated at four characters per token for the "
                                      "request and the reply; model calls and seconds are the station's "
                                      "own writers and tints during the request's window")}
    try:
        if submitted and resolved and 0 < resolved - submitted <= 24 * 3600:
            if rows is None:
                rows = model_calls_rows(submitted, resolved)
            window = [r for r in rows if submitted <= float(r.get("at") or 0) < resolved]
            costs["model_calls"] = len(window)
            costs["model_seconds"] = round(sum(int(r.get("working_ms") or r.get("ms") or 0)
                                               for r in window) / 1000.0, 1)
            costs["model_tokens_out"] = sum(int(r.get("eval_count") or 0) for r in window)
            costs["model_tokens_in"] = sum(int(r.get("prompt_eval_count") or 0) for r in window)
    except Exception:  # noqa: BLE001
        pass
    return costs


def pine_journal_write(req_id: int, when: str, request: str, reply: str,
                       resolved_at: float | None = None, kind: str = "inbox",
                       rows: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    """Write <id>.md and <id>.json for one resolved request. Sync (files);
    call it in a thread from the loop."""
    req_id = int(req_id)
    request = str(request or "").strip()
    reply = str(reply or "").strip() or "(resolved)"
    submitted = _pine_when_epoch(when)
    resolved = float(resolved_at or time.time())
    costs = pine_journal_costs(request, reply, submitted, resolved, rows)
    images = _pine_request_images(request)
    title = " ".join(re.sub(r"\n\nAttached (?:images|files):.*\Z", "", request, flags=re.S).split())[:80]
    meta = {"id": req_id, "kind": kind, "when": str(when or ""), "submitted_at": submitted,
            "resolved_at": resolved,
            "resolved": time.strftime("%Y-%m-%d %H:%M", time.localtime(resolved)),
            "title": title or f"Request #{req_id}", "request": request, "reply": reply,
            "images": images, "costs": costs,
            "graph": pine_journal_graph(req_id, request, reply),
            "markdown_path": f"data/pine_journal/{req_id}.md", "version": 1}
    quoted = "\n".join("> " + line for line in request.splitlines()) or "> (no text)"
    pictures = "".join(f"\n![attachment]({url})\n" for url in images)
    md = (f"# Request #{req_id}\n\n- Submitted: {when}\n- Resolved: {meta['resolved']}\n"
          f"- Tokens in (estimated): {costs['tokens_in']}\n- Tokens out (estimated): {costs['tokens_out']}\n"
          f"- Open for: {costs['elapsed_s']} s\n- Station model calls inside the window: "
          f"{costs['model_calls']} ({costs['model_seconds']} s working)\n\n"
          f"## The request\n\n{quoted}\n{pictures}\n## The reply\n\n{reply}\n\n"
          f"## Costs\n\n| measure | value |\n|---|---|\n| tokens in | {costs['tokens_in']} |\n"
          f"| tokens out | {costs['tokens_out']} |\n| open for | {costs['elapsed_s']} s |\n"
          f"| station model calls | {costs['model_calls']} |\n| station model seconds | {costs['model_seconds']} |\n\n"
          f"_{costs['note']}_\n")
    PINE_JOURNAL_DIR.mkdir(parents=True, exist_ok=True)
    for name, body in ((f"{req_id}.md", md),
                       (f"{req_id}.json", json.dumps(meta, ensure_ascii=False, indent=1))):
        temp = PINE_JOURNAL_DIR / (name + ".tmp")
        temp.write_text(body, encoding="utf-8")
        temp.replace(PINE_JOURNAL_DIR / name)
    return meta


def pine_journal_backfill() -> int:
    """Every archived resolution without a page gets one. Sync; once."""
    if _PINE_JOURNAL_BACKFILLED[0]:
        return 0
    _PINE_JOURNAL_BACKFILLED[0] = True
    try:
        history = PINE_COMPLETED_PATH.read_text(encoding="utf-8")
    except Exception:  # noqa: BLE001
        return 0
    PINE_JOURNAL_DIR.mkdir(parents=True, exist_ok=True)
    blocks = _PINE_COMPLETED_BLOCK_RE.findall(history)
    missing = [(int(i), r, s, t, p) for i, r, s, t, p in blocks
               if not (PINE_JOURNAL_DIR / f"{int(i)}.json").exists()]
    if not missing:
        return 0
    earliest = min((_pine_when_epoch(s) for _, _, s, _, _ in missing if _pine_when_epoch(s)), default=0.0)
    rows: list[dict[str, Any]] = []
    try:
        if earliest and time.time() - earliest <= 14 * 86400:
            rows = model_calls_rows(earliest, time.time())
    except Exception:  # noqa: BLE001
        rows = []
    written = 0
    for req_id, resolved_when, submitted, text, reply in missing:
        try:
            pine_journal_write(req_id, submitted.strip(), text.strip(), reply.strip(),
                               resolved_at=_pine_when_epoch(resolved_when) or None, rows=rows)
            written += 1
        except Exception:  # noqa: BLE001
            continue
    return written


def _pine_journal_ids() -> list[int]:
    try:
        return sorted((int(p.stem) for p in PINE_JOURNAL_DIR.glob("*.json") if p.stem.isdigit()),
                      reverse=True)
    except Exception:  # noqa: BLE001
        return []


def pine_journal_index() -> list[dict[str, Any]]:
    """Newest first; one light row per page. Sync."""
    pine_journal_backfill()
    out: list[dict[str, Any]] = []
    for req_id in _pine_journal_ids():
        try:
            meta = json.loads((PINE_JOURNAL_DIR / f"{req_id}.json").read_text(encoding="utf-8"))
        except Exception:  # noqa: BLE001
            continue
        costs = meta.get("costs") or {}
        out.append({"id": req_id, "when": meta.get("when"), "resolved_at": meta.get("resolved_at"),
                    "resolved": meta.get("resolved"), "title": meta.get("title"),
                    "kind": meta.get("kind") or "inbox", "images": len(meta.get("images") or []),
                    "tokens_in": costs.get("tokens_in", 0), "tokens_out": costs.get("tokens_out", 0),
                    "elapsed_s": costs.get("elapsed_s", 0), "model_calls": costs.get("model_calls", 0),
                    "model_seconds": costs.get("model_seconds", 0.0)})
    return out


def pine_journal_page(req_id: int) -> dict[str, Any] | None:
    pine_journal_backfill()
    ids = _pine_journal_ids()
    if int(req_id) not in ids:
        return None
    try:
        meta = json.loads((PINE_JOURNAL_DIR / f"{int(req_id)}.json").read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return None
    older = [i for i in ids if i < int(req_id)]
    newer = [i for i in ids if i > int(req_id)]
    # Page one is the newest request; the next page is the older one.
    meta["previous_id"] = newer[-1] if newer else None
    meta["next_id"] = older[0] if older else None
    meta["page"] = ids.index(int(req_id)) + 1
    meta["pages"] = len(ids)
    return meta


def _comfy_output_files(history: dict[str, Any]) -> list[str]:
    """Flatten a ComfyUI /history response into a newest-first list of output
    image filenames. History is insertion-ordered oldest→newest, so a reversed
    walk with de-dup yields the most recent renders first."""
    files: list[str] = []
    for entry in (history or {}).values():
        outputs = (entry or {}).get("outputs") or {}
        for out in outputs.values():
            if not isinstance(out, dict):
                continue
            # SaveImage lists under "images", SaveVideo under "images" or
            # "video" depending on version — accept any list of outputs.
            for group in out.values():
                if not isinstance(group, list):
                    continue
                for img in group:
                    if (
                        isinstance(img, dict)
                        and img.get("type") == "output"
                        and img.get("filename")
                    ):
                        files.append(str(img["filename"]))
    seen: set[str] = set()
    unique: list[str] = []
    for name in reversed(files):
        if name in seen:
            continue
        if name.lower().endswith(
            (".png", ".jpg", ".jpeg", ".webp", ".mp4", ".webm")
        ):
            seen.add(name)
            unique.append(name)
    return unique


async def _submit_generation(
    tags: str, request_text: str, kind: str = "image"
) -> tuple[str, str]:
    """Submit one render to ComfyUI, record it (with node-graph complexity +
    a start time for the duration stat), and start tracking it. Shared by the
    voice path and the gallery 'regenerate' button. Returns (prompt_id,
    model_name); raises on submit failure."""
    workflow = (
        _comfy_video_workflow(tags) if kind == "video" else _comfy_workflow(tags)
    )
    model_name = _workflow_model_name(workflow)
    complexity = _workflow_complexity(workflow)
    async with httpx.AsyncClient(timeout=15) as client:
        response = await client.post(
            f"{COMFYUI_URL}/prompt", json={"prompt": workflow}
        )
        response.raise_for_status()
        prompt_id = str((response.json() or {}).get("prompt_id") or "")
    _COMFY_LAST_USED[0] = time.time()      # #796: the idle-unload clock
    started_at = time.time()
    append_generation({
        "ts": int(started_at),
        "request": request_text,
        "tags": tags,
        "model": model_name,
        "prompt_id": prompt_id,
        "files": [],
        "status": "queued",
        "kind": kind,
        "stats": complexity,
    })
    if prompt_id:
        asyncio.create_task(
            _track_generation(prompt_id, started_at, complexity))
    return prompt_id, model_name


def _restyled_request(user_text: str) -> tuple[str, str]:
    """'Do that again but as X' -> previous render's subject + the new style.
    Returns (request_text, restyled_from)."""
    if not is_restyle_request(user_text):
        return user_text, ""
    last = read_generations(1)
    if not last:
        return user_text, ""
    restyled_from = str(last[0].get("request") or last[0].get("tags") or "")
    base_subject = extract_image_prompt(restyled_from)
    return f"{base_subject}. New style: {user_text}", restyled_from


async def _comfy_prompt(user_text: str, settings: dict[str, Any]) -> tuple[str, str]:
    """Final ComfyUI prompt: the literal dictated request first, tags after."""
    request_text, restyled_from = _restyled_request(user_text)
    subject = extract_image_prompt(request_text)
    tags = await image_tags(request_text, settings)
    prompt = subject if subject.lower() == tags.lower() else f"{subject}. {tags}"
    return prompt, restyled_from


async def comfyui_generate(
    user_text: str, settings: dict[str, Any], kind: str = "image",
    direct: bool = False,
) -> str:
    """Submit a ComfyUI render. Normally returns an instruction the DJ model
    rephrases in persona; `direct=True` returns a finished user-facing line
    instead, used when the radio is on so an image request never waits behind
    the DJ's heavy model use (#476) — the render is already queued either
    way."""
    prompt, restyled_from = await _comfy_prompt(user_text, settings)
    try:
        _prompt_id, model_name = await _submit_generation(
            prompt, user_text, kind
        )
    except Exception as exc:
        # #1152: a failed render is the doctor's page. Self-heal in the
        # background (throttled inside), and SAY so - the operator's
        # complaint was an error with nobody doing anything about it.
        fire_and_forget(comfy_doctor(
            reason=f"a {kind} render failed to submit", auto=True))
        if direct:
            return (f"That {kind} could not be generated — ComfyUI is "
                    f"unavailable or misconfigured ({exc}). The Comfy "
                    "Doctor is on it in the background; the console on "
                    "the panel shows the repair.")
        return (
            f"Tell the user the {kind} could not be generated because ComfyUI "
            f"is unavailable or misconfigured (technical error: {exc}), and "
            "that the station's Comfy Doctor has already started a "
            "background repair - its console on the panel shows each step, "
            "and the render can be asked for again in a minute or two."
        )
    # The order goes through the DJ desk (#354): a commission placed at
    # the box while the show is on becomes an ad read on air — processed
    # and managed, loudly, by the pair.
    if _RADIO.get("on"):
        asyncio.create_task(dj_ad(
            f"a listener's LIVE {kind} commission, ordered through the "
            f"Pine Box this very minute — the subject: {user_text[:140]} "
            "— congratulate the patron and promise it on the gallery "
            "wall shortly", remember=False))
    reused = (
        f" It reuses the previous render's subject ('{restyled_from[:120]}') "
        "with the new style applied."
        if restyled_from
        else ""
    )
    took = (
        " Video renders take several minutes." if kind == "video" else ""
    )
    if direct:
        # A finished, user-facing line — no model call, so it returns
        # instantly even while the DJ system is hammering Ollama (#476).
        show = (settings.get("read_back_prompts", True))
        article = "an" if kind[:1] in "aeiou" else "a"
        return (
            f"On it — {article} {kind} is rendering now on ComfyUI "
            f"({model_name})"
            + (f". Prompt: {prompt}" if show else "") + f".{reused}{took} "
            "It will appear in the PineBox gallery when it finishes.")
    if not settings.get("read_back_prompts", True):
        return (
            f"A {kind} render was submitted to ComfyUI using {model_name}."
            f"{reused} Do NOT reveal the prompt or tag list. Instead, hype it "
            f"up in one short line — something like 'a great {kind} is "
            "cooking, you won't believe what's coming back' — and say it "
            f"will appear in the PineBox gallery when finished.{took}"
        )
    return (
        f"A {kind} render was submitted to ComfyUI using {model_name}. "
        f"The exact prompt sent was: {prompt}.{reused} Tell the user the "
        f"{kind} is rendering now, and read that prompt back to them verbatim "
        "so they know exactly what was requested. It will appear in the "
        f"PineBox gallery when finished.{took}"
    )


# --- Open WebUI passthrough ------------------------------------------------


# #787/#788: the wake phrases that hand a spoken line somewhere — said to
# the box after the button press. "hey LLM …" (and friends) route to Open
# WebUI, tools and all; "hey DJ …" routes to the booth. The list lives in
# settings["wake"] so words can be turned off, added and removed from the
# panel; the BUILTIN ids keep generous matchers because STT mangles "LLM"
# freely (l l m / lm / alum / el el em) and "DJ" almost as much.
_BUILTIN_WAKE = {
    "hey-llm": re.compile(
        r"^\s*(?:hey|hay|ok(?:ay)?)[\s,]+(?:the\s+)?"
        r"(?:l\.?\s?l\.?\s?m\.?|llm|lm|alum|el+\s+el+\s+em+)"
        r"\b[\s,.:!?—-]*", re.IGNORECASE),
    "ask-webui": re.compile(
        r"^\s*ask[\s,]+(?:the\s+)?(?:open\s*)?"
        r"(?:web\s?u\.?i\.?|webui|l\.?\s?l\.?\s?m\.?|llm)\b[\s,.:!?—-]*",
        re.IGNORECASE),
    "open-webui": re.compile(
        r"^\s*(please\s+)?(ask|use|send to|query|on)?\s*open ?web ?ui\b"
        r"[:,]?\s*(to\s+|and\s+|for\s+)?", re.IGNORECASE),
    "hey-dj": re.compile(
        r"^\s*(?:hey|hay|yo|ok(?:ay)?)[\s,]+(?:the\s+)?"
        r"(?:d\.?\s?j\.?s?|deejays?|dee\s+jays?)\b[\s,.:!?—-]*",
        re.IGNORECASE),
}
_WAKE_ROUTES = ("webui", "dj")


def validate_wake(raw: Any) -> dict[str, Any]:
    base = DEFAULT_SETTINGS["wake"]
    if not isinstance(raw, dict):
        return json.loads(json.dumps(base))
    words = []
    for w in (raw.get("words") if isinstance(raw.get("words"), list)
              else base["words"]):
        if not isinstance(w, dict):
            continue
        phrase = str(w.get("phrase") or "").strip()[:60]
        if not phrase:
            continue
        wid = str(w.get("id") or re.sub(r"[^a-z0-9]+", "-",
                                        phrase.lower())).strip("-")[:40]
        words.append({
            "id": wid, "phrase": phrase,
            "route": w.get("route") if w.get("route") in _WAKE_ROUTES
            else "webui",
            "on": bool(w.get("on", True)),
            "builtin": wid in _BUILTIN_WAKE,
        })
    return {"enabled": bool(raw.get("enabled", True)), "words": words}


def _wake_norm(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", (text or "").lower()).strip()


def wake_route(text: str, settings: dict[str, Any] | None = None) \
        -> tuple[str, str] | None:
    """(route, question) when the line starts with an enabled wake word."""
    cfg = (settings or load_settings()).get("wake") or {}
    if not cfg.get("enabled", True):
        return None
    for w in cfg.get("words") or []:
        if not w.get("on", True):
            continue
        rx = _BUILTIN_WAKE.get(w.get("id") or "")
        if rx:
            m = rx.match(text or "")
            if m:
                return (w["route"], (text or "")[m.end():].strip())
            continue
        # Custom words match on normalized token prefix.
        want = _wake_norm(w.get("phrase") or "")
        if not want:
            continue
        got = _wake_norm(text)
        if got == want or got.startswith(want + " "):
            toks = (text or "").split()
            return (w["route"], " ".join(toks[len(want.split()):]).strip())
    return None


_RESCUE_RX = re.compile(
    r"(?:where(?:'s| is| did)\s+(?:the\s+)?"
    r"(?:radio|station|show|broadcast|pine\s*fm)"
    r"|what(?:'s| is| has)?\s+(?:happened|happening|going on|wrong)\s+"
    r"(?:to|with)\s+(?:the\s+)?"
    r"(?:radio|station|network|system|show|broadcast|pine\s*fm|box"
    r"|d\.?\s?j\.?s?|deejays?|hosts?|banter)"
    r"|why\s+(?:is|isn'?t|was)\s+(?:the\s+)?"
    r"(?:radio|station|network|show|broadcast|music|sound)"
    r"|(?:fix|reboot|restart|revive|resurrect)\s+(?:the\s+)?"
    r"(?:radio|station|network|system|show|broadcast|pine\s*fm)"
    r"|bring\s+(?:up|back)\s+(?:the\s+)?"
    r"(?:radio|station|pine\s*fm|show|broadcast)"
    r"|get\s+(?:the\s+)?(?:radio|station|show|broadcast)\s+back"
    r"|is\s+(?:the\s+)?(?:radio|station|show)\s+"
    r"(?:up|on|down|dead|alive|working|broken))", re.IGNORECASE)


_RESCUE_NOUN = re.compile(
    r"\b(?:radio|station|pine\s*fm|broadcast|d\.?\s?j\.?s?|deejays?"
    r"|hosts?|banter|dialogue)\b", re.IGNORECASE)
_RESCUE_MOOD = re.compile(
    r"\b(?:where|down|dead|gone|missing|broke(?:n)?|offline|quiet|"
    r"silent|bro|wtf|fuck(?:ing)?|restore|fix|help|back|at)\b",
    re.IGNORECASE)
_RESCUE_MUSICY = re.compile(
    r"\b(?:play|request|song|track|tune|volume|louder|quieter|turn)\b",
    re.IGNORECASE)
_RESCUE_HARD = re.compile(
    r"\b(?:down|dead|where|fix|restore|gone|missing|broke(?:n)?|"
    r"offline)\b", re.IGNORECASE)


def is_radio_rescue(text: str) -> bool:
    """#827/#839: 'where is the radio station', 'what happened to the
    network', 'reboot the radio' — and the SHORT SHOUTS: 'station bro',
    'dead station', 'where the fuck is the station', 'station is down',
    'where the station at'. Any brief line that names the station and
    carries a where/dead/fix mood is the same order: run the whole
    tree, fix every branch, end with a station somebody can hear."""
    t = str(text or "")
    if _RESCUE_RX.search(t):
        return True
    if len(t) <= 70 and _RESCUE_NOUN.search(t) and _RESCUE_MOOD.search(t):
        # A music order that happens to name the radio is not a rescue —
        # unless it ALSO says the station is gone.
        if _RESCUE_MUSICY.search(t) and not _RESCUE_HARD.search(t):
            return False
        return True
    return False


_PLAY_ON_DEVICE_RX = re.compile(
    r"play\s+(?:the\s+)?(?:audio|music|sound|d\.?\s?j\.?s?|deejays?"
    r"|broadcast|show|station|radio)\b"
    r".{0,50}?\b(?:out of|on|through|from|to)\s+(?:the\s+)?"
    r"(?:device|nabu|pine\s*box|box|speaker)", re.IGNORECASE)


def is_play_on_device(text: str) -> bool:
    """#827: 'play the music and the DJs out of the device' — a routing
    order in plain words."""
    return bool(_PLAY_ON_DEVICE_RX.search(str(text or "")))


def is_openwebui_request(text: str) -> bool:
    hit = wake_route(text)
    if hit:
        return hit[0] == "webui"
    return False


def strip_openwebui_prefix(text: str) -> str:
    hit = wake_route(text)
    if hit and hit[0] == "webui":
        return hit[1] or (text or "").strip()
    return (text or "").strip()


async def ask_openwebui(text: str, model: str) -> str:
    query = strip_openwebui_prefix(text)
    headers = {"Content-Type": "application/json"}
    if OPENWEBUI_API_KEY:
        headers["Authorization"] = f"Bearer {OPENWEBUI_API_KEY}"
    # #788: the agent's own model is an ollama name Open WebUI may not
    # serve. Prefer the configured ask-model; when a model 400s, fall back
    # to the first real model Open WebUI lists and try once more.
    preferred = os.getenv("OPENWEBUI_ASK_MODEL", "").strip() or model
    try:
        async with httpx.AsyncClient(timeout=180) as client:
            async def _try(m: str) -> httpx.Response:
                return await client.post(
                    f"{OPENWEBUI_URL}/api/chat/completions",
                    headers=headers,
                    json={"model": m,
                          "messages": [{"role": "user", "content": query}],
                          "stream": False})
            response = await _try(preferred)
            if response.status_code == 400:
                listing = await client.get(f"{OPENWEBUI_URL}/api/models",
                                           headers=headers)
                ids = [m.get("id") for m in
                       (listing.json().get("data") or [])
                       if m.get("id") and m["id"] != "arena-model"]
                if ids and preferred not in ids:
                    preferred = ids[0]
                    response = await _try(preferred)
            if response.status_code == 400:
                # This Open WebUI's process_chat pipeline is refusing
                # everything ('NoneType' startswith). The ollama proxy
                # behind it still answers — the model minus the tool
                # pipeline beats an apology.
                response = await client.post(
                    f"{OPENWEBUI_URL}/ollama/api/chat", headers=headers,
                    json={"model": preferred,
                          "messages": [{"role": "user", "content": query}],
                          "stream": False})
                response.raise_for_status()
                answer = (response.json().get("message") or {}).get(
                    "content") or ""
                return str(answer).strip() or \
                    "Open WebUI returned an empty response."
            response.raise_for_status()
            data = response.json()
        answer = data["choices"][0]["message"]["content"]
        return str(answer).strip() or "Open WebUI returned an empty response."
    except Exception as exc:
        return (
            "Open WebUI could not be reached or is not configured. "
            f"Technical error: {exc}"
        )


# --- Mirror conversations into an Open WebUI "Pinebox" folder ---------------

_BG_TASKS: set[Any] = set()


# #852: the main event loop, captured at startup, so work handed over
# from a worker thread has somewhere to go.
_MAIN_LOOP: list[Any] = [None]


@app.on_event("startup")
async def _startup_capture_loop() -> None:
    try:
        _MAIN_LOOP[0] = asyncio.get_running_loop()
    except RuntimeError:
        _MAIN_LOOP[0] = None


def fire_and_forget_speech(coro: Any) -> None:
    """Speech we can later cancel from the Stop button."""
    try:
        task = asyncio.create_task(coro)
    except RuntimeError:
        return
    _SPEECH_TASKS.add(task)
    task.add_done_callback(_SPEECH_TASKS.discard)


def fire_and_forget(coro: Any) -> None:
    try:
        task = asyncio.create_task(coro)
    except RuntimeError:
        # #852: called from a worker thread, where there is no running
        # loop. fire_and_forget_speech has always guarded this; this one
        # raised instead — and sting_due runs in a thread, so the raise
        # tore down the whole talk round (~40 times in a day). Hand the
        # work to the main loop when we can find it, and say so rather
        # than swallowing a real misuse in silence.
        loop = _MAIN_LOOP[0]
        if loop is not None and loop.is_running():
            try:
                asyncio.run_coroutine_threadsafe(coro, loop)
                return
            except Exception:  # noqa: BLE001
                pass
        try:
            coro.close()
        except Exception:  # noqa: BLE001
            pass
        pipeline_log("repair", "background work was requested off the "
                               "event loop and could not be scheduled "
                               "(#852)")
        return
    _BG_TASKS.add(task)
    task.add_done_callback(_BG_TASKS.discard)


def _ow_load_state() -> dict[str, Any]:
    try:
        return json.loads(OPENWEBUI_STATE.read_text())
    except Exception:
        return {}


def _ow_save_state(state: dict[str, Any]) -> None:
    try:
        OPENWEBUI_STATE.parent.mkdir(parents=True, exist_ok=True)
        OPENWEBUI_STATE.write_text(json.dumps(state))
    except Exception:
        pass


async def _ow_folder_id(client: httpx.AsyncClient) -> str | None:
    folders = (await client.get(f"{OPENWEBUI_URL}/api/v1/folders/")).json()
    for folder in folders:
        if folder.get("name") == PINEBOX_FOLDER:
            return folder["id"]
    await client.post(f"{OPENWEBUI_URL}/api/v1/folders/", json={"name": PINEBOX_FOLDER})
    folders = (await client.get(f"{OPENWEBUI_URL}/api/v1/folders/")).json()
    for folder in folders:
        if folder.get("name") == PINEBOX_FOLDER:
            return folder["id"]
    return None


async def mirror_to_openwebui(user_text: str, answer: str, model: str) -> None:
    # Best-effort: log every voice turn into the Open WebUI "Pinebox" folder.
    # ponytail: single rolling chat, read-modify-write per turn, no locking -
    # fine for one sequential speaker; add a lock if it ever runs concurrently.
    if not OPENWEBUI_API_KEY:
        return

    headers = {
        "Authorization": f"Bearer {OPENWEBUI_API_KEY}",
        "Content-Type": "application/json",
    }
    now = int(time.time())
    uid = str(uuid.uuid4())
    aid = str(uuid.uuid4())
    umsg = {
        "id": uid, "parentId": None, "childrenIds": [aid], "role": "user",
        "content": user_text, "timestamp": now, "models": [model],
    }
    amsg = {
        "id": aid, "parentId": uid, "childrenIds": [], "role": "assistant",
        "content": answer, "timestamp": now, "model": model, "modelName": model,
    }

    try:
        async with httpx.AsyncClient(timeout=15, headers=headers) as client:
            state = _ow_load_state()
            folder_id = state.get("folder_id") or await _ow_folder_id(client)
            if not folder_id:
                return

            chat_id = state.get("chat_id")
            fresh = (not chat_id) or (
                now - int(state.get("last_ts", 0)) > PINEBOX_GAP_SECONDS
            )

            if fresh:
                title = " ".join(user_text.split())[:60] or "PineBox conversation"
                chat = {
                    "id": "", "title": f"\U0001f3a4 {title}",
                    "models": [model], "messages": [umsg, amsg],
                    "history": {"currentId": aid, "messages": {uid: umsg, aid: amsg}},
                    "files": [], "tags": [], "timestamp": now * 1000, "params": {},
                }
                created = await client.post(
                    f"{OPENWEBUI_URL}/api/v1/chats/new", json={"chat": chat}
                )
                created.raise_for_status()
                chat_id = created.json().get("id")
                await client.post(
                    f"{OPENWEBUI_URL}/api/v1/chats/{chat_id}/folder",
                    json={"folder_id": folder_id},
                )
            else:
                got = (
                    await client.get(f"{OPENWEBUI_URL}/api/v1/chats/{chat_id}")
                ).json()
                chat = got.get("chat") or {}
                hist = chat.setdefault(
                    "history", {"currentId": None, "messages": {}}
                )
                prev = hist.get("currentId")
                if prev and prev in hist.get("messages", {}):
                    hist["messages"][prev].setdefault("childrenIds", []).append(uid)
                    umsg["parentId"] = prev
                hist.setdefault("messages", {})[uid] = umsg
                hist["messages"][aid] = amsg
                hist["currentId"] = aid
                chat.setdefault("messages", []).extend([umsg, amsg])
                updated = await client.post(
                    f"{OPENWEBUI_URL}/api/v1/chats/{chat_id}", json={"chat": chat}
                )
                updated.raise_for_status()

            state.update({"folder_id": folder_id, "chat_id": chat_id, "last_ts": now})
            _ow_save_state(state)
    except Exception:
        pass  # never let logging affect the voice response


# --- Voice output via Home Assistant TTS -----------------------------------


# The token is pasted once and must survive settings resets, container
# rebuilds and edits made from other machines — so it also lives in its own
# file next to settings.json.
HA_TOKEN_PATH = data_path("ha_token")


def _ha_token_persist(token: str, player: str) -> None:
    try:
        HA_TOKEN_PATH.parent.mkdir(parents=True, exist_ok=True)
        prev = _ha_token_stored()
        HA_TOKEN_PATH.write_text(json.dumps({
            "token": token or prev["token"],
            "player": player or prev["player"],
        }))
    except Exception:
        pass


def _ha_token_stored() -> dict[str, str]:
    try:
        data = json.loads(HA_TOKEN_PATH.read_text())
        return {
            "token": str(data.get("token") or ""),
            "player": str(data.get("player") or ""),
        }
    except Exception:
        return {"token": "", "player": ""}


def _ha_creds(reply: bool = False) -> tuple[str, str]:
    """(token, media_player): token from env/settings/file; player from the
    selected route, with an explicit reply player allowed to override."""
    voice = load_settings().get("voice_out") or {}
    backup = _ha_token_stored()
    token = HA_TOKEN or str(voice.get("ha_token") or "") or backup["token"]
    reply_player = str(voice.get("reply_media_player") or "")
    # #814: a reply player left pointing at the OTHER satellite is a stale
    # remnant of a device switch, not a choice — 640 replies played out of
    # the retired PineVoice in 18h while every route said Nabu. A reply
    # override only counts when it names something that is not the
    # unselected satellite.
    _stale_reply = (
        (reply_player == PINEVOICE_SATELLITE
         and _RADIO.get("voice_device") == "nabu")
        or (reply_player == NABU_SATELLITE
            and _RADIO.get("voice_device") == "pine"))
    if reply and reply_player and not _stale_reply:
        player = reply_player
    elif _RADIO.get("voice_device") == "nabu":
        player = NABU_SATELLITE
    elif _RADIO.get("voice_device") == "pine":
        player = PINEVOICE_SATELLITE
    else:
        player = HA_MEDIA_PLAYER or str(voice.get("media_player") or "") \
            or backup["player"]
    return token, player


def box_talk_ok(reply: bool = False) -> bool:
    """The master switch for the Pine Box (#638).

    Routing used to be decided at thirty separate call sites, and the roads
    that never asked — a chime, a probe, an ack, the hold shelf replaying
    something from an hour ago — went out the speaker anyway. Off means off:
    every outbound road asks this first, so there is nothing left to forget.

    What the switch governs is the STATION. Answering YOU is a different
    job (#647): with the show off the box, the box is still an assistant —
    ask it for a render and it replies as it always did. That road passes
    `reply=True` and is governed by the reply routing alone.
    """
    if reply:
        return (_RADIO.get("reply_to") or "box") != "off"
    return bool(_RADIO.get("box_talk", True))


def box_overridden() -> dict[str, Any] | None:
    """Is the station ignoring the routing the operator chose, and why?

    #757. Derived from the state rather than recorded when a line is spoken:
    hanging it on dj_speak meant you sat looking at a silent box until the
    next line happened to be written, which on a quiet stretch is a minute
    or more of precisely the confusion this exists to prevent. The condition
    is knowable the moment the picker moves, so it is known then.

    There is exactly one way this happens today — the master switch off
    while the DJ voice is pointed at the box — and it was invisible."""
    wanted = _RADIO.get("voice_to") or "box"
    if wanted not in ("box", "both") or box_talk_ok():
        return None
    return {
        "wanted": wanted,
        "actually": "here",
        "fix": "box_talk",
        "why": "The DJ voice is routed to the Pine Box, but the Pine Box "
               "master switch is OFF — so the show is coming out of this "
               "page instead. Turn the switch on and it goes to the box.",
    }


def box_worth_healing() -> bool:
    """Is the STATION routed to the speaker right now (#690)?

    The repair machinery ran on its own clocks — a hold-shelf pass that
    knocked every twenty seconds, a wedge check that rebuilt the Wyoming
    entry, a dead-air strike that restarted Home Assistant — and none of
    them asked whether anybody was actually trying to use the box. With the
    Pine Box switch off they kept going: the show plays on the page exactly
    as designed, the speaker is deliberately idle, and the station spends
    the night reconnecting to a device it has been told not to talk to,
    blinking "The DJs are on it" on every open panel over a fault that is
    not one. A switched-off box is not a broken box.

    This governs the BACKGROUND repairs only, which is why the reply road
    is not in it. Answering YOU is on demand: it needs a working link at
    the moment you ask the box something, and that road repairs itself
    where it fails (home_assistant_say's retry plan, satellite_ready's
    probe). What it does not need is a clock rebuilding the socket all
    night while nobody is talking to it — and reply_to defaults to "box",
    so counting it here would have left the switch doing nothing at all.
    """
    if not box_talk_ok():
        return False
    return ((_RADIO.get("voice_to") or "box") in ("box", "both")
            or (_RADIO.get("music_to") or "here") in ("box", "both"))


PIPER_VOICES = [
    "en_US-lessac-medium", "en_US-joe-medium", "en_US-amy-low",
    "en_US-hfc_female-medium", "en_US-kusal-medium",
]


# Which voice speaks which kind of line (#59).
VOICE_EVENTS = ("default", "submit", "complete", "render", "doc", "alert")


def _event_voice(event: str) -> str:
    voice = load_settings().get("voice_out") or {}
    per_event = voice.get("event_voices") or {}
    return str(
        per_event.get(event) or per_event.get("default") or voice.get("voice")
        or ""
    ).strip()


# --- The ladder: no written line goes unheard (#784) ------------------------
#
# "i need these voices to broadcast first and foremost. no matter the
# settings... There should never be dialogue not being played."
#
# Measured live: 29 of 165 booth rows carried aired="never" — written, given a
# voice, and never heard. Every one belonged to the HOST (vl_1a04bb8c) or the
# drop guy (vl_31d384e6), the two speakers whose voices are CLONES. The
# co-host, on a real Piper voice, did not appear in that list once. That is
# the whole diagnosis in a line.
#
# The clone road already fell back to Piper when an engine wobbled:
#     engine, forced = "piper", _event_voice(who) or _event_voice("default")
# but _event_voice reads voice_out.event_voices and voice_out.voice, and on
# this station both are EMPTY — so `forced` came out "", voice_generate was
# handed a blank voice, the Piper allowlist rejected it, and the "fallback"
# raised exactly like the thing it was catching. A ladder whose bottom rung is
# a setting nobody filled in is a ladder into a hole.
#
# The bottom rung is the live Piper catalog now, which cannot be empty while
# Piper is up, and every render goes through one helper.
# Lines that could not be rendered at all, kept until an engine answers. The
# station used to mark these aired="never" and move on, which is precisely
# the "dialogue not being played" the operator will not accept (#784).
_RENDER_BACKLOG: list[dict[str, Any]] = []
RENDER_BACKLOG_PATH = data_path("render_backlog.json")


def render_backlog_save() -> None:
    try:
        RENDER_BACKLOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        temporary = RENDER_BACKLOG_PATH.with_suffix(".tmp")
        temporary.write_text(json.dumps(_RENDER_BACKLOG), encoding="utf-8")
        temporary.replace(RENDER_BACKLOG_PATH)
    except OSError as exc:
        pipeline_log("drop", "unrecorded dialogue persistence failed",
                     extra=type(exc).__name__)


def render_backlog_load() -> None:
    if _RENDER_BACKLOG:
        return
    try:
        rows = json.loads(RENDER_BACKLOG_PATH.read_text(encoding="utf-8"))
        if isinstance(rows, list):
            _RENDER_BACKLOG.extend(r for r in rows
                                   if isinstance(r, dict) and r.get("text"))
    except (OSError, ValueError):
        pass


def render_backlog_ack(line_id: str) -> None:
    """Retire recovery debt only after verified completion on an output."""
    if line_id and any(str(row.get("id") or "") == line_id
                       for row in _RENDER_BACKLOG):
        _RENDER_BACKLOG[:] = [row for row in _RENDER_BACKLOG
                             if str(row.get("id") or "") != line_id]
        render_backlog_save()
        render_backlog_top()

_PIPER_CATALOG: dict[str, Any] = {"at": 0.0, "voices": []}


async def piper_catalog() -> list[str]:
    """Piper's own list of what it can speak, cached five minutes."""
    if _PIPER_CATALOG["voices"] and time.time() - _PIPER_CATALOG["at"] < 300:
        return _PIPER_CATALOG["voices"]
    try:
        # #850: SIX SECONDS, not forever. Every other call site already
        # wrapped this in wait_for; this one did not, and #842 put it on
        # the hot path of every render — so a wyoming-piper that accepts
        # the connection and then dies mid-frame (its log shows exactly
        # that) left `await reader.readline()` blocked for ever and hung
        # voice_render_any before a single rung was tried.
        names = await asyncio.wait_for(piper_voices(), 6)
    except Exception:
        names = []
    if names:
        _PIPER_CATALOG.update({"at": time.time(), "voices": names})
    return _PIPER_CATALOG["voices"]


async def piper_fallback_voice(who: str = "") -> str:
    """A Piper voice that DEFINITELY exists, for when a clone cannot render.

    Walked in order of how much it still sounds like the show: this speaker's
    own configured voice, then the station's other Piper voices, then whatever
    Piper actually has installed. Only an unreachable Piper returns ""."""
    dj = dj_settings()
    seats = {"dj": "voice", "host": "voice", "cohost": "cohost_voice",
             "third": "third_voice", "drop": "drop_voice"}
    mine = str(dj.get(seats.get(who, "voice")) or "").strip()
    # This speaker's OWN voice first, when it happens to be a Piper one, then
    # anything the operator set explicitly for this event.
    for name in (mine, _event_voice(who)):
        name = (name or "").strip()
        if name and not VOICE_ID_SHAPE.match(name):
            return name
    catalog = await piper_catalog()
    if catalog:
        # #516, and the reason this does NOT simply borrow the co-host's
        # voice: an engine wobble must never collapse the pair into one
        # person. Voices already spoken for by another seat are off the
        # table, and the pick is stable per speaker so a stand-in does not
        # change voice line to line.
        taken = {str(dj.get(field) or "").strip()
                 for seat, field in seats.items() if seat != who}
        free = [v for v in catalog if v not in taken]
        pool = [v for v in free if v.startswith(("en_", "en-"))] or free             or catalog
        # By SEAT, not by hash: with as many voices free as there are seats
        # this is distinct by construction, where a hash only usually is.
        order = ["dj", "cohost", "third", "drop"]
        seat = order.index(who) if who in order else len(order)
        return pool[seat % len(pool)]
    # Piper is unreachable: nothing here can help, and the caller says so.
    return _event_voice("default") or ""


def clone_fallback_voice(who: str = "") -> str:
    """A library (clone) voice that exists, for when PIPER is the dead one.

    #784: the first cut of this ladder could only ever cross one way — a
    clone falling back to Piper. Then wyoming-piper wedged: its port stayed
    open, its voice list came back empty, and every Piper rung failed with
    "No such voice" while XTTS was rendering perfectly. The co-host, whose
    voice is a Piper one, could not speak a word. Any voice beats silence
    means BOTH directions."""
    dj = dj_settings()
    seats = {"dj": "voice", "host": "voice", "cohost": "cohost_voice",
             "third": "third_voice", "drop": "drop_voice"}
    tries = [str(dj.get(seats.get(who, "voice")) or "")]
    tries += [str(dj.get(f) or "") for f in seats.values()]
    for name in tries:
        name = name.strip()
        if name and VOICE_ID_SHAPE.match(name) and voice_ref_path(name):
            return name
    try:
        for meta in sorted(VOICES_DIR.glob("vl_*")):
            if voice_ref_path(meta.name):
                return meta.name
    except OSError:
        pass
    return ""


def _model_call_for(text: str) -> dict[str, Any]:
    """Which model call produced this line, matched on its words (#782).

    A line is written inside a ROUND and spoken one turn at a time, so there
    is no id tying the two together. Matching on a distinctive run of the
    line against the last few answers is imperfect and honest: when it finds
    nothing the dossier simply says the writing time is unknown rather than
    attaching whichever call happened to be last."""
    probe = " ".join(str(text or "").split())[:60].lower()
    if len(probe) < 20:
        return {}
    for call in reversed(_MODEL_CALLS):
        if probe in " ".join(str(call.get("text") or "").split()).lower():
            return {k: v for k, v in call.items() if k != "text"}
    return {}


def _model_call_full(text: str) -> dict[str, Any]:
    """The WHOLE exchange that produced this line - prompt, script and all.

    _model_call_for matches against the first 400 characters of the answer,
    which is all the hot path needs. A round is written as one script and
    spoken a turn at a time, so a turn from the back half of a long round
    falls outside that window entirely; this one searches the full script
    kept since #861, then relaxes the probe once before giving up. Used by
    the provenance card only, so it can afford to look twice."""
    probe = " ".join(str(text or "").split()).lower()
    if len(probe) < 12:
        return {}
    for width in (60, 30):
        key = probe[:width]
        if not key:
            continue
        for call in reversed(_MODEL_CALLS):
            hay = " ".join(str(call.get("script")
                               or call.get("text") or "").split()).lower()
            if key in hay:
                return dict(call)
    return {}


async def voice_render_any(text: str, voice: str, engine: str = "",
                           fx: dict[str, float] | None = None,
                           who: str = "") -> dict[str, Any] | None:
    """Render this line through the assigned actor whenever possible.

    THE contract for #784: ordinary lines use every available engine to stay
    audible; configured booth actors retain their identity and wait on the
    retry shelf if both of their clone-engine paths are unavailable. The rungs,
    in order —
      1. the voice and engine asked for;
      2. the OTHER cloning engine when the voice is a library clone — both
         XTTS and F5 take the same reference, so a clone is never stranded
         because one of the two is down;
      3. Piper, in a voice guaranteed to exist (above);
      4. and that is the floor: while Piper answers, something is spoken.
    Every fallback is logged and put on the drop log, because a line that went
    out in a stand-in voice is something the operator must be able to SEE
    rather than discover by ear."""
    text = str(text or "").strip()
    if not text:
        return None
    engine = engine or voice_engine_for(voice)
    # #784: LENGTH is the other way a written line could not be rendered. The
    # box road cuts a long line into slider-sized pieces; the page road never
    # did, so anything over VOICE_MAX_CHARS came back 413 and both "retries"
    # resent exactly the same oversized text. An intro runs past it easily,
    # which is why intros and ad reads are over-represented in the silent
    # rows. Cut it here, speak the pieces, and join them so every caller
    # still gets one clip back.
    if len(text) > VOICE_MAX_CHARS:
        cap = max(200, VOICE_MAX_CHARS - 80)
        pieces = sentence_chunks(text, cap=cap, most=24)
        # sentence_chunks cuts at sentence boundaries, so a long line with no
        # full stops in it comes back as ONE oversized piece — and then every
        # rung below 413s identically and the line is lost. That is not a
        # theory: the model writes to a 1000-character reply budget against a
        # VOICE_MAX_CHARS of 800, so the host's long monologues land here
        # constantly. Guarantee the pieces fit, by force if the text will not
        # cooperate.
        forced_pieces: list[str] = []
        for piece in (pieces or [text]):
            while len(piece) > VOICE_MAX_CHARS:
                cut = piece.rfind(" ", 0, VOICE_MAX_CHARS - 1)
                if cut < 40:
                    cut = VOICE_MAX_CHARS - 1
                forced_pieces.append(piece[:cut].strip())
                piece = piece[cut:].strip()
            if piece:
                forced_pieces.append(piece)
        pieces = [p for p in forced_pieces if p]
        if len(pieces) > 1:
            # #993: JOIN THE FILES, NOT THE URLs.
            #
            # _store_media returns {"path": "/media/<key>"}, which is a
            # SERVED path. Both rungs below took it for a filename: the
            # concat handed "/media/x.wav" to ffmpeg, which cannot open
            # it, and the fallback did Path("/media/x.wav").read_bytes(),
            # which raises FileNotFoundError - an OSError - and returned
            # None. So every line over VOICE_MAX_CHARS rendered all of
            # its pieces, paid the engine in full for them, and then threw
            # the audio away and reported failure.
            #
            # It was invisible because the log line below fired on `made`
            # being non-empty, i.e. BEFORE either rung ran - the glass
            # said "spoken in 2 and joined" on exactly the renders that
            # were being lost. Measured: advert reads sat at 0 of 9 lines
            # rendered for the whole session while station IDs, same loop,
            # same engine, same voice, went 4 of 4 - the only difference
            # between them is that an ad is ~1000 characters and an ID is
            # ~60. Every road that writes long lost every long line.
            made: list[str] = []
            secs = 0.0
            for piece in pieces:
                part = await voice_render_any(piece, voice, engine,
                                              fx=fx, who=who)
                if part and part.get("path"):
                    made.append(part["path"])
                    secs += float(part.get("seconds") or 0)
            files = [str(f) for f in (_media_file(m) for m in made) if f]
            if len(files) == len(pieces):
                out: dict[str, Any] | None = None
                if len(files) > 1:
                    joined = await asyncio.to_thread(
                        _call_concat_blocking, files, False)
                    if joined:
                        out = _store_media(joined, "wav")
                if out is None and len(files) == 1:
                    try:
                        out = _store_media(
                            Path(files[0]).read_bytes(), "wav")
                    except OSError:
                        out = None
                if out is not None:
                    # #993: and CARRY THE DURATION. _store_media reports
                    # bytes, not seconds, so the joined clip came back
                    # saying it was zero seconds long and every shelf that
                    # banked one reported nothing on it.
                    out.setdefault("seconds", round(secs, 2))
                    pipeline_log("voice",
                                 f"a {len(text)}-character line was too "
                                 f"long to render in one piece - spoken in "
                                 f"{len(files)} and joined, "
                                 f"{out.get('seconds')}s (#784/#993)")
                    return out
            pipeline_log("drop", f"a {len(text)}-character line was cut into "
                                 f"{len(pieces)} and {len(made)} came back, "
                                 "but the complete audio could not be joined; "
                                 "the full line remains owed (#1057)")
            return None
    # #794: "any voice listed is usable." An engine-prefixed pick
    # (voxcpm:vl_x, cosyvoice:vl_x…) is still a library CLONE — the raw
    # string just doesn't look like one, so the clone road never built its
    # rungs, and a cast actor on a dead bench engine went to the retry
    # shelf forever: the silence the operator heard. The reference IS the
    # identity, so falling through to the same clone on xtts/f5 keeps the
    # casting decision while the bench engine is down or out of memory.
    _rung_pfx, _rung_bare = split_engine_voice(voice)
    is_clone = bool(VOICE_ID_SHAPE.match((_rung_bare or voice) or ""))
    seats = {"dj": "voice", "host": "voice", "cohost": "cohost_voice",
             "third": "third_voice", "drop": "drop_voice"}
    selected = str(dj_settings().get(seats.get(who, "")) or "").strip()
    # A named on-air actor is a casting decision. Do not substitute it merely
    # because the fast relief path is active; a failed take goes to retry.
    actor_locked = bool(selected and voice == selected and who in seats)
    # #842: the stand-in is ALWAYS resolved. It used to be withheld from a
    # locked actor, which removed the Piper rung entirely — so when both
    # clone engines were down a named DJ had NO last resort and the line
    # was simply lost, while the drop log claimed "Piper included". A
    # stand-in voice is a smaller loss than silence, every time.
    try:
        # #850: belt as well as braces. The stand-in is looked up on
        # EVERY render now, so it gets its own ceiling — a slow catalog
        # must never delay the engines that were going to work.
        stand_in = await asyncio.wait_for(piper_fallback_voice(who), 8)
    except Exception:  # noqa: BLE001
        stand_in = ""
    rungs: list[tuple[str, str, str]] = []
    if is_clone:
        bare = _rung_bare or voice
        if _rung_pfx and _rung_pfx not in ("xtts", "f5"):
            rungs.append((voice, _rung_pfx, ""))
            # #1021: the engine the cache says is UP goes first; one it
            # says is DOWN goes last. xtts stays ahead on a tie.
            _order = ["xtts", "f5"]
            if voicepolicy_avoid_piper():
                _order.sort(key=lambda e: (
                    0 if voicepolicy_engine_ready(e)
                    else (2 if voicepolicy_engine_known_down(e) else 1)))
            for _eng in _order:
                rungs.append((bare, _eng,
                              f"{_rung_pfx} would not render it — the same "
                              f"clone through {_eng}, identity kept (#794)"))
        else:
            clone_engine = _rung_pfx if _rung_pfx in ("xtts", "f5") else (
                engine if engine in ("xtts", "f5") else str(
                    (voice_meta(bare) or {}).get("engine") or "xtts"))
            pick = str(dj_settings().get("clone_engine") or "")
            if pick in ("xtts", "f5") and not _rung_pfx:
                clone_engine = pick
            # #1021: the clone_engine pick above undid whatever the
            # router decided, so the route-around is applied here too -
            # a resident engine that is down by its last check is not
            # the first rung while the other is up.
            clone_engine = voicepolicy_route_around(clone_engine, who)
            rungs.append((bare, clone_engine, ""))
            other = "f5" if clone_engine == "xtts" else "xtts"
            # #866: under the cast lock the OTHER engine is deliberately
            # not resident — naming it here would wake a second 23-24G
            # model to say one line, on a pool the writer already
            # shares. Fall to Piper instead; the cast returns the moment
            # the host's own engine answers.
            #
            # #1021: ...except under the avoid-Piper policy, where the
            # other engine is still tried - as a stand-in, identity kept
            # - unless its last health check says it is down, in which
            # case naming it would only wait on a dead socket. This was
            # the most common road by which a named DJ reached Piper.
            if cast_engine_locked() and other != host_clone_engine():
                if voicepolicy_avoid_piper() \
                        and not voicepolicy_engine_known_down(other):
                    rungs.append((bare, other,
                                  f"{clone_engine} would not render it — "
                                  f"the same clone through {other} as a "
                                  "stand-in, identity kept, cast lock or "
                                  "not (#1021)"))
                else:
                    if voicepolicy_avoid_piper():
                        voicepolicy_say(
                            f"ladder:{other}:down:{who}",
                            f"{who or 'line'}: Piper is next on the ladder "
                            f"after {clone_engine} — {other} is down by its "
                            "last health check and the cast is locked to "
                            f"{host_clone_engine()} (#1021)")
                    rungs.append((stand_in or "", "piper",
                                  f"{clone_engine} would not render it and "
                                  "the cast is locked to one engine — a "
                                  "stand-in rather than loading a second "
                                  "model (#866)"))
            else:
                rungs.append((bare, other,
                              f"{clone_engine} would not render it — "
                              f"the same clone through {other} (#784)"))
        if stand_in and stand_in != voice:
            rungs.append((stand_in, "piper",
                          "BOTH cloning engines refused — airing this line "
                          "in a stand-in voice rather than losing it; the "
                          "cast returns the moment an engine answers (#842)"))
    else:
        rungs.append((voice, engine, ""))
        if stand_in and stand_in != voice:
            rungs.append((stand_in, "piper", "the selected Piper voice is "
                          "unavailable — a stand-in keeps the line moving (#784)"))
        borrowed = clone_fallback_voice(who)
        if borrowed:
            rungs.append((borrowed, "xtts", "Piper is not answering — the "
                          "line goes out in a borrowed cloned voice (#784)"))
            rungs.append((borrowed, "f5", "Piper is not answering — the "
                          "line goes out in a borrowed cloned voice (#784)"))
    # #842: THE FLOOR, for every line without exception. Piper's default
    # voice needs no library, no GPU and no director — if this rung fails
    # the box itself is gone. It used to be skipped for a locked actor,
    # which is precisely how a cast line ended up with no audio at all.
    rungs.append(("", "piper", "every named voice refused — the line goes "
                               "out plain rather than not at all (#784)"))
    tried: list[str] = []
    for name, eng, why in rungs:
        prep_lane = _PREP_RENDER_ENGINE.get()
        extra_lane = bool(prep_lane and eng != prep_lane)
        if extra_lane and _ENGINE_PREP_BY.get(eng):
            tried.append(f"{eng}: another preparation booth holds this engine")
            continue
        if extra_lane:
            _ENGINE_PREP_BY[eng] = 1
        try:
            clip = await voice_generate(text, name, eng,
                                        fx=None if not name else fx)
        except Exception as exc:
            # #784: WHY, not just that. "every engine refused" with no reason
            # attached is not a diagnosis, and this is the last line of
            # defence in the whole station.
            detail = getattr(exc, "detail", None) or str(exc)
            tried.append(f"{eng}/{name or '(default)'}: "
                         f"{type(exc).__name__} {str(detail)[:120]}")
            clip = None
        finally:
            if extra_lane:
                _ENGINE_PREP_BY.pop(eng, None)
        if clip and clip.get("path"):
            # #782: the road this line actually took, carried on the clip so
            # the dossier can show every engine that refused before one
            # spoke — that is most of the interesting story of a bad night.
            if tried:
                clip["tried"] = list(tried)
            if why:
                clip["fallback"] = why
                pipeline_log("voice", why,
                             extra=f"{who or 'line'}: {text[:180]}")
                note_drop(who, text, why[:200])
            return clip
    # Piper itself is unreachable or has nothing installed. Say so loudly:
    # this is the only remaining way a line can fail, and it is a station
    # fault rather than a line fault.
    pipeline_log("drop", "NOTHING could render this line — every engine "
                         "refused it, Piper included (#784) — the rungs "
                         "and their reasons are in the detail",
                 extra=(f"{who or 'line'} - {len(text)} chars: "
                        f"{text[:300]}\n\n"
                        + "\n".join(tried)))
    return None


_BACKLOG_BUSY = [False]
_HOLD_DRAIN_LOCK = asyncio.Lock()


async def box_hold_drain_one() -> dict[str, Any] | None:
    """Serialize head selection, verified playback and exact-row retirement."""
    if (radio_paused() or not box_talk_ok()
            or (_RADIO.get("voice_to") or "box") not in ("box", "both")):
        return None
    # 2026-09-07: a box whose firmware is provably not running (every
    # port refuses) cannot take a held line; trying takes the air floor
    # for the length of a verified-playout wait, six rows deep, over and
    # over. The shelf keeps its rows until the wire answers again.
    try:
        if _WIRE_LAST.get("at") and nabu_firmware_down(_WIRE_LAST):
            return None
    except Exception:  # noqa: BLE001
        pass
    owned = await _floor_take("the ordered held-dialogue queue")
    try:
        async with _HOLD_DRAIN_LOCK:
            if (not _BOX_HOLD or radio_paused() or not box_talk_ok()
                    or (_RADIO.get("voice_to") or "box") not in ("box", "both")):
                return None
            held = _BOX_HOLD[0]
            if time.time() < float(held.get("retry_after") or 0):
                return None
            if not await _replay_held(held):
                # A failed head keeps its place. Back off without dropping an
                # unheard line or allowing its answer to pass it in the queue.
                held["tries"] = int(held.get("tries") or 0) + 1
                held["retry_after"] = time.time() + min(90, 5 * 2 ** min(held["tries"], 4))
                _box_hold_save()
                if held["tries"] == 3 or held["tries"] % 6 == 0:
                    pipeline_log("air", "held dialogue still awaits verified playback",
                                 extra=f"{held['tries']} attempts; head retained for retry")
                return None
            # Explicit operator edits can change the queue while playback is
            # awaited. Never pop whichever unrelated row now occupies index 0.
            _BOX_HOLD[:] = [row for row in _BOX_HOLD if row is not held]
            _box_hold_save()
            return held
    finally:
        _floor_drop(owned)


async def _box_hold_drain_soon() -> None:
    """#850: nudge the hold shelf so a rescued box-bound line plays now
    rather than at the next scheduled drain."""
    try:
        await asyncio.sleep(0.5)
        n = 0
        while _BOX_HOLD and n < 6:
            if not await box_hold_drain_one():
                break
            n += 1
    except Exception:  # noqa: BLE001
        pass


async def render_backlog_drain() -> None:
    """Air the lines that could not be rendered when they were written.

    #784: the operator's rule is that a written line is heard, and a station
    fault is a delay rather than a deletion. Anything the ladder could not
    speak waits here and is tried again whenever the show next opens its
    mouth; the moment an engine answers it goes out on the page feed and its
    booth row stops saying it is waiting."""
    if _BACKLOG_BUSY[0] or not _RENDER_BACKLOG or radio_paused():
        return
    _BACKLOG_BUSY[0] = True
    owned = False
    try:
        owned = await _floor_take("the ordered conversation recovery queue")
        for held in list(_RENDER_BACKLOG):
            if not _RENDER_BACKLOG or radio_paused():
                break
            delivery = _PAGE_DELIVERIES.get(str(held.get("delivery_id") or ""))
            if delivery and delivery.get("state") != "error":
                break                    # its tail cannot overtake an uncompleted head
            clip = held.get("clip")
            if not clip or not _media_file(str(clip.get("path") or "")):
                clip = await voice_render_any(str(held.get("text") or ""),
                                          str(held.get("voice") or ""),
                                          fx=held.get("fx"),
                                          who=str(held.get("who") or ""))
            if not (clip and clip.get("path")):
                break                   # still nothing; try again next time
            held["clip"] = clip
            render_backlog_save()
            # #850: a line that was BOUND FOR THE BOX goes to the box.
            # The drain only ever republished to the page feed, so a
            # rescued line reached the website and still never reached
            # the speaker the operator is listening to.
            if (held.get("to_box") and not any(
                    str(row.get("id") or "") == str(held.get("id") or "")
                    for row in _BOX_HOLD)):
                try:
                    box_hold(clip, str(held.get("text") or ""),
                             str(held.get("who") or ""),
                             str(held.get("id") or ""))
                    fire_and_forget(_box_hold_drain_soon())
                except Exception:  # noqa: BLE001
                    pass
            delivery_id = page_feed_append({
                "url": f"{clip['path']}?t={clip['sig']}",
                "text": held.get("text", ""), "voice": held.get("voice", ""),
                "speech": True, "row_id": str(held.get("id") or ""),
                "who": str(held.get("who") or "dj"),
                "kind": str(held.get("kind") or "interject"),
                "remember_text": str(held.get("remember_text") or held.get("text") or ""),
                "seconds": float(clip.get("seconds") or 0),
            })
            if not delivery_id:
                break
            held["delivery_id"] = delivery_id
            render_backlog_save()
            for row in reversed(_RADIO.get("chat") or []):
                if row.get("id") == held.get("id"):
                    row["aired"] = "published"
                    row["air_at"] = time.time()
                    page_delivery_apply(row, delivery_id)
                    break
            pipeline_log("air", "a line that could not be rendered earlier "
                                "has been published for page playout (#784)",
                         extra=str(held.get("text") or "")[:300])
            break                        # completion will release the next FIFO line
    except Exception:
        pass                            # the backlog is a rescue, not a risk
    finally:
        _floor_drop(owned)
        _BACKLOG_BUSY[0] = False


def render_backlog_top() -> None:
    """Ask for a drain without waiting on one."""
    if _RENDER_BACKLOG and not _BACKLOG_BUSY[0]:
        try:
            asyncio.get_running_loop().create_task(render_backlog_drain())
        except RuntimeError:
            pass


def _voice_style(text: str) -> str:
    """Personality: how a spoken line is dressed before it is synthesised."""
    voice = load_settings().get("voice_out") or {}
    prefix = str(voice.get("personality_prefix") or "").strip()
    suffix = str(voice.get("personality_suffix") or "").strip()
    if prefix:
        text = f"{prefix} {text}"
    if suffix:
        text = f"{text} {suffix}"
    return text


_SPEECH_TASKS: set[asyncio.Task[Any]] = set()


async def stop_speaking() -> dict[str, Any]:
    """Cancel anything we have queued and stop a media_player mid-sentence.
    An assist satellite exposes no stop service, so its current line finishes."""
    cancelled = 0
    for task in list(_SPEECH_TASKS):
        if not task.done():
            task.cancel()
            cancelled += 1
    _SPEECH_TASKS.clear()

    token, player = _ha_creds()
    _reply_token, reply_player = _ha_creds(reply=True)
    stopped_player = False
    # #786: Nabu's clips actually play through its companion MEDIA PLAYER,
    # which HAS a stop service — the "no stop service" rule is a pine-only
    # fact. The core device must be the one speaker the stop button stops.
    stop_target = ""
    if player == NABU_SATELLITE and NABU_MEDIA_PLAYER:
        stop_target = NABU_MEDIA_PLAYER
    elif player and not player.startswith("assist_satellite."):
        stop_target = player
    if token and stop_target:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                response = await client.post(
                    f"{HA_URL}/api/services/media_player/media_stop",
                    headers={"Authorization": f"Bearer {token}"},
                    json={"entity_id": stop_target},
                )
                stopped_player = response.status_code < 400
        except Exception:
            pass
    return {
        "cancelled_queued": cancelled,
        "stopped_player": stopped_player,
        "satellite_note": (
            "the satellite has no stop service, so a line already playing "
            "finishes"
            if player.startswith("assist_satellite.") and not stop_target
            else ""
        ),
    }



# Whether the satellite answered recently, so we do not keep firing announce
# calls at a device that is switched off. Home Assistant logs a warning for
# every one of those, and they were arriving in bursts.
_SAT_ALIVE: dict[str, Any] = {"ok": True, "checked": 0.0, "entity": ""}
_SAT_RECHECK = 60.0


async def satellite_ready(heal: bool = True, reply: bool = False) -> bool:
    """Cheap, cached liveness for the speaker. Pessimistic by design: if we
    cannot tell, we assume it is there and let the call fail once.

    `heal=False` asks the question without acting on the answer (#690) —
    for a status readout, which wants to know whether the box is up and has
    no business rebuilding its link as a side effect of being looked at."""
    token, player = _ha_creds(reply=reply)
    if not (token and player):
        _SAT_ALIVE["ok"] = False
        return False
    now = time.time()
    if (_SAT_ALIVE.get("entity") == player
            and now - _SAT_ALIVE["checked"] < _SAT_RECHECK):
        return bool(_SAT_ALIVE["ok"])

    _SAT_ALIVE.update({"checked": now, "entity": player})
    try:
        async with httpx.AsyncClient(timeout=6) as client:
            response = await client.get(
                f"{HA_URL}/api/states/{player}",
                headers={"Authorization": f"Bearer {token}"})
            state = (response.json() or {}).get("state", "")
        _SAT_ALIVE["ok"] = state not in ("unavailable", "unknown", "")
        if not _SAT_ALIVE["ok"]:
            # heal_on_unavailable: an entity that reads unavailable while its
            # config entry still reads loaded is a dead Wyoming socket, and
            # nothing else in Home Assistant will notice. Rebuild it now so
            # the next thing anyone says gets through, rather than waiting
            # for somebody to press recover.
            #
            # #690: only when somebody is genuinely trying to reach the box
            # through this probe. The two roads that use it — a reply, and
            # music to the box — each refuse at their own door when their
            # routing is off, so reaching here means the box IS wanted. A
            # status readout asks with heal=False: reading a dashboard is
            # not a reason to restart a speaker link.
            if heal:
                fire_and_forget(satellite_selfheal())
    except Exception:
        _SAT_ALIVE["ok"] = True          # cannot tell; do not silence the box
    return bool(_SAT_ALIVE["ok"])


# What the satellite was doing last time anyone asked, and when. Not the same
# question as satellite_ready: alive is a minute-stale fact and stays true all
# day, but busy changes second to second (#206).
_SAT_BUSY: dict[str, Any] = {"state": "", "at": 0.0, "entity": ""}
_SAT_BUSY_FRESH = 1.5
# Whether this agent is on the speaker right now, and when it last was. Our
# own announce puts the satellite in "responding" too, so without both of
# these the show reads its own voice as a stranger and gags itself.
_SPEAKING = [0]                    # depth, not a flag: announces can nest
# 2026-09-07: WHEN DID DIALOGUE LAST AIR. Stamped by every road that puts
# a spoken line out (the single-line door and the round stream), read by
# dj_banter's shelf-only refusal: at 100% talk the live writer is refused
# while the reserve catches up, and with the deep lane serial the reserve
# never caught up - the operator heard records and nothing else for an
# hour. Past this many seconds of no dialogue, one live round is written
# anyway (it is still tinted before it airs), at most one every rest.
_DIALOGUE_AT = [time.time()]
_STARVED_WRITE_AT = [0.0]
DIALOGUE_STARVED_AFTER = 240.0
DIALOGUE_STARVED_REST = 300.0          # one starved round at a time


def dialogue_starved() -> tuple[bool, int]:
    """(is the air starved of dialogue, seconds since the last line)."""
    try:
        quiet = int(time.time() - float(_DIALOGUE_AT[0] or 0))
        starved = (quiet >= DIALOGUE_STARVED_AFTER
                   and time.time() - float(_STARVED_WRITE_AT[0] or 0)
                   >= DIALOGUE_STARVED_REST)
        return starved, quiet
    except Exception:  # noqa: BLE001
        return False, 0
_SPOKE_AT = [0.0]
# WHICH line is going out right now (#742). `speaking` was a bare boolean and
# the entry was only written to chat once the line had FINISHED airing — so
# for the whole minute a line was actually sounding it did not exist in the
# booth at all, and "jump to what is being said" had nothing to jump to. This
# is that line, published from the moment it is handed over, carrying the id
# the finished entry will land under so the two are one row and not two.
_SPEAKING_NOW: dict[str, Any] = {}
_SPEAKING_NOW_MAX = 300.0          # a stuck announce ages out rather than lying
# #748: the timeline of a COALESCED round — one clip, many turns. The
# stream is how most of the show actually goes out, and it never touched
# _SPEAKING_NOW at all, so the booth could not follow it.
_STREAM_NOW: dict[str, Any] = {}
# When we last saw a REAL human turn (the box in listening/processing).
# This box is announce-only so it stays 0 — which is the point: a
# "responding" state with no recent real turn is a wedge, not a person.
_SAT_SAW_TURN_AT = [0.0]
# When any engine last STARTED rendering — a 30-second XTTS render is the
# show working, not dead air (#394): the watchdog restarting mid-round
# was how the openers aired twice in seventy seconds.
_LAST_SYNTH = [0.0]
_SYNTH_TRIED = [0.0]              # #852: attempted, as distinct from done

# One writer plus one long looker, never a pile: every chat call to ollama
# goes through this gate, because the show's clocks stacking unbounded
# concurrent calls is exactly what wedged the chat queue server-side.
#
# #1080: OLLAMA_LANES is how many asks one model may hold at once. It
# must match the host's OLLAMA_NUM_PARALLEL (a runner launched `-np 1`
# serialises a second ask, see the measurement below); with two slots on
# the host the second ask decodes beside the first instead of behind it.
# Set in compose beside OLLAMA_URL; the code default stays one lane.
def _ollama_lanes_env() -> int:
    try:
        return max(1, min(4, int(str(os.getenv("OLLAMA_LANES", "1") or "1").strip())))
    except Exception:  # noqa: BLE001
        return 1
OLLAMA_LANES = _ollama_lanes_env()
_OLLAMA_GATE = asyncio.Semaphore(2 * OLLAMA_LANES)
# #1079: ...AND ONE PERMIT PER MODEL BEHIND IT.
#
# Every llama-server runner on this box is launched `-np 1`, so ollama
# serialises requests per model. Measured: two simultaneous 31b calls
# span 35.24s against 31.5s of summed compute - the second spent 18.35s
# purely queued, and throughput was identical to running them in turn.
# CROSS-model overlap is different and genuinely free: 31b held 4.2
# tok/s while e2b simultaneously ran at 31-66, because e2b's second of
# compute slots into 31b's fourteen.
#
# A single semaphore of two permits the useless case and does not
# guarantee the useful one. This gives exactly the overlap that pays.
_OLLAMA_ONE: dict[str, asyncio.Semaphore] = {}
_OLLAMA_JOBS: dict[str, dict[str, Any]] = {}
_OLLAMA_DEFERRED: dict[str, int] = {}
_OLLAMA_DEFERRED_CATEGORIES: dict[str, int] = {}
_WRITING_DEFERRED: ContextVar[int] = ContextVar("writing_deferred", default=0)


class WritingDeferred(Exception):
    """No model ran; retained writing must yield without a quality verdict."""
    def __init__(self, reason: str):
        super().__init__(reason)
        self.turns: list[dict[str, Any]] | None = None


def writing_room_state() -> dict[str, Any]:
    """Actual model admission, including waiters invisible to the global gate."""
    now = time.time()
    jobs = [{"id": identity, "model": row["model"], "purpose": row["purpose"],
             "category": row.get("category") or _ollama_category(row["purpose"])[0],
             "state": row["state"], "seconds": round(now - row["at"], 2)}
            for identity, row in list(_OLLAMA_JOBS.items())]
    _station_cap = _ollama_category_cap("station")
    _tint_cap = _ollama_category_cap("tint")
    return {"station_limit_per_model": _station_cap, "tint_limit_per_model": _tint_cap,
            "repertoire_limit_per_model": 1, "sfx_reserve_limit_per_model": 1,
            "lanes_per_model": OLLAMA_LANES,                       # #1080
            "category_limits_per_model": {"station": _station_cap, "tint": _tint_cap,
                                          "repertoire": 1,
                                          "sfx_reserve": 1, "interactive": None},
            "active": sum(row["state"] == "active" for row in jobs),
            "waiting": sum(row["state"] == "waiting" for row in jobs),
            "deferred": dict(_OLLAMA_DEFERRED),
            "deferred_by_category": dict(_OLLAMA_DEFERRED_CATEGORIES), "jobs": jobs}


def _ollama_lane(model: str) -> asyncio.Semaphore:
    """One permit for each model, made on first use (OLLAMA_LANES of them, #1080)."""
    key = str(model or "")
    lane = _OLLAMA_ONE.get(key)
    if lane is None:
        lane = asyncio.Semaphore(OLLAMA_LANES)
        _OLLAMA_ONE[key] = lane
    return lane


def _system2_critical_work() -> bool:
    """#1080: whether the current task is preparing a System2 job whose slot
    has started or starts within twenty minutes. That work rides one more
    tint permit than the background roads, so the hour's own due segment
    is not queued behind a memo for the day after tomorrow."""
    try:
        getter = globals().get("system2_current_work")
        work = getter() if callable(getter) else None
        if not work:
            return False
        start = float((work.get("template") or {}).get("start") or 0)
        return bool(start) and start - time.time() < 1200.0
    except Exception:  # noqa: BLE001
        return False


def _ollama_category_cap(category: str, purpose: str = "") -> int:
    """The admission cap for a category, lanes and the schedule's own work
    counted (#1080)."""
    # 2026-09-08 (the cupboard audit): the tint cap is a WAITING depth,
    # not a refusal rate. At lanes + 1 the fourth tint caller was refused
    # at once and came back in six seconds: 70 of 148 asks in 26 minutes
    # bounced, the whole-round shelf requests nine times in ten, and seven
    # written rounds sat untouched for half an hour while the lane ran at
    # 1.35 of 2. Three waiters behind the lanes keep the runner packed and
    # the callers in one FIFO instead of a retry loop.
    base = {"station": max(2, OLLAMA_LANES + 1), "tint": max(2, OLLAMA_LANES + 3),
            "repertoire": 1, "sfx_reserve": 1}.get(category, 0)
    if base and category == "tint" and _system2_critical_work():
        base += 1
    return base
_OUR_VOICE_FOR = 4.0


def _busy_with_someone(state: str) -> bool:
    # "listening" and "processing" are unambiguous: a person at the mic.
    if state in ("listening", "processing"):
        _SAT_SAW_TURN_AT[0] = time.time()
        return True
    # "responding" is the trap. This board is ANNOUNCE-only (supported
    # features == 1), so it CANNOT hold a real conversation — a lingering
    # "responding" while we are not speaking is our own tail or, far more
    # often, the BL606P wedged mid-stream (root-cause audit), never a human
    # being answered. Deferring to it gagged the show for up to two minutes
    # against a phantom. So it only counts as busy if we actually saw a real
    # listening/processing turn in the last 30s (a genuine human exchange);
    # absent that, "responding" is a wedge and the show talks over it.
    if state != "responding" or _SPEAKING[0]:
        return False
    if time.time() - _SPOKE_AT[0] <= _OUR_VOICE_FOR:
        return True                     # still our own line's tail
    return time.time() - _SAT_SAW_TURN_AT[0] < 30.0


async def satellite_busy() -> bool:
    """True when the box is in the middle of something with a person.

    One speaker, two writers: the DJ announces through this agent, and a
    spoken question is answered by Home Assistant itself, which this agent
    never sees. An announce preempts — it cuts whatever is playing off
    mid-word — so patter arriving while someone is being answered takes the
    answer away. Deliberately uncached beyond a second and a half: ready-ness
    is cached for a minute, and a minute-old answer to this question would
    either gag the show or never fire at all."""
    token, player = _ha_creds()
    if not (token and player):
        return False
    now = time.time()
    if (_SAT_BUSY.get("entity") == player
            and now - _SAT_BUSY["at"] < _SAT_BUSY_FRESH):
        return _busy_with_someone(str(_SAT_BUSY["state"]))
    try:
        async with httpx.AsyncClient(timeout=4) as client:
            response = await client.get(
                f"{HA_URL}/api/states/{player}",
                headers={"Authorization": f"Bearer {token}"})
        state = str((response.json() or {}).get("state") or "")
    except Exception:
        return False                     # cannot tell; the show goes on
    _SAT_BUSY.update({"state": state, "at": now, "entity": player})
    # A reply cannot run two straight minutes on this board. A satellite
    # stuck in "responding" is a wedged assist session (#369, #373) — it
    # gagged whole stretches of the show — so heal it and stop treating
    # it as a person mid-answer.
    if state in ("listening", "processing"):
        _SAT_SAW_TURN_AT[0] = now
    if state == "responding":
        since = _SAT_BUSY.setdefault("responding_since", now)
        # A wedge is recognised in ~25s now, not 120s (root-cause audit):
        # this box cannot hold a two-minute human turn, so a long
        # "responding" with us silent AND no recent real turn is a wedge.
        # satellite_selfheal itself now probes TCP and only rebuilds a
        # genuinely dead socket, so calling it early is cheap.
        wedged = (now - since > 25.0 and not _SPEAKING[0]
                  and now - _SAT_SAW_TURN_AT[0] > 30.0)
        if wedged:
            _SAT_BUSY["responding_since"] = now
            # #690: only chase a wedge on a link something is using.
            if box_worth_healing():
                pipeline_log("air", "satellite lingering in 'responding' "
                                    "with no live turn — checking the link")
                asyncio.create_task(satellite_selfheal())
            return False
    else:
        _SAT_BUSY.pop("responding_since", None)
    return _busy_with_someone(state)


# How recently the satellite's config entry was rebuilt. Reloading in a tight
# loop would be worse than the fault it is fixing.
_HEAL_LAST = [0.0]
# When one actually succeeded, which is a different question.
_HEALED_AT = [0.0]
HEAL_COOLDOWN = 90.0
# Consecutive "reachable but stalling" observations — each one stretches the
# cooldown so the app stops hammering a box that is merely slow.
_HEAL_MISS = [0]


def _heal_cooldown() -> float:
    """The reload cooldown, stretched while the box keeps stalling rather
    than failing (root-cause audit): a slow BL606P should not be reloaded
    every 90s — that only cancels its in-flight connect."""
    return HEAL_COOLDOWN * (2 ** min(_HEAL_MISS[0], 4))


# The deepest rung of the repair ladder (user directive): when link
# rebuilds keep failing, the agent restarts Home Assistant ITSELF through
# the Docker control socket mounted into this container.
_HEAL_STREAK = [0]
_HA_RESTART_LAST = [0.0]
HA_RESTART_COOLDOWN = 900.0

# #712: OFF by default now, and the reason is worth keeping. Restarting Home
# Assistant to clear a wedged speaker fired 51 times through the socket proxy
# and restarted HA 49 times — every 20 to 60 minutes overnight — and each
# restart severed the Wyoming stream mid-clip so the box never received its
# AudioStop and looped the fragment it was holding. The cure was the disease.
# The cooldown that was supposed to bound it did not: spark-agent's own
# watchdog restarts the container on three failed 8-second health probes,
# and every restart zeroes _HA_RESTART_LAST and _BOX_LAST_OK, disarming both
# guards. Set HA_RESTART_ESCALATION=1 to put the ladder back.
HA_RESTART_ESCALATION = os.getenv(
    "HA_RESTART_ESCALATION", "0").lower() in ("1", "true", "yes", "on")


async def ha_restart_container() -> bool:
    """Order Docker to restart the homeassistant container — the full
    repair the wedge sometimes needs, now in the DJs' own hands. Goes
    through a restarts-only docker-socket-proxy on loopback (ALLOW_RESTARTS
    only; CONTAINERS is off), so this container cannot create/start/delete
    containers, only restart by name."""
    now = time.time()
    if now - _HA_RESTART_LAST[0] < HA_RESTART_COOLDOWN:
        return False
    # A restart the LAST one did not cure must not be repeated (audit: the
    # 15-minute HA power-cycle loop for a speaker that is simply switched
    # off). Only re-arm once the box has actually carried a line since the
    # previous restart — a restart cannot fix an unplugged speaker, so
    # escalating again is pointless and disruptive.
    if _HA_RESTART_LAST[0] > 0 and _BOX_LAST_OK[0] <= _HA_RESTART_LAST[0]:
        repair_note("Home Assistant was already restarted and the box "
                    "still has not spoken — not power-cycling again; the "
                    "speaker itself likely needs attention")
        return False
    # Stamp only AFTER the guard, and only when we actually attempt, so a
    # single failed attempt does not silently block the real repair for
    # fifteen minutes (audit).
    _HA_RESTART_LAST[0] = now
    try:
        async with httpx.AsyncClient(timeout=90) as client:
            reply = await client.post(
                "http://127.0.0.1:2375/containers/homeassistant"
                "/restart?t=10")
        ok = reply.status_code in (204, 304)
    except Exception as exc:
        repair_note(f"tried to restart Home Assistant and could not: "
                    f"{exc}"[:160])
        return False
    if not ok:
        # The silent branch (audit): a denied/misrouted restart used to
        # vanish. Now the proxy's status lands in the ledger.
        repair_note(f"Home Assistant restart was refused (HTTP "
                    f"{reply.status_code}) — check the docker-socket-proxy")
        return False
    if ok:
        repair_note("FULL repair: restarted Home Assistant itself — the "
                    "speaker link was wedged past rebuilding")
        _HEAL_STREAK[0] = 0
        await asyncio.sleep(45)         # HA takes a moment to come back
        if _RADIO.get("on"):
            asyncio.create_task(dj_banter(None, lines=3, angle=(
                "Break the fourth wall as engineers again (#368): the "
                "speaker link was so wedged you just power-cycled the "
                "ENTIRE Home Assistant brain of the building to get back "
                "on air. Announce it like surgeons stepping out of "
                "theatre — drained, triumphant, slightly appalled at "
                "what you had to do.")))
    return ok


# #793: the dead-link ladder — the exact rungs a human climbed on
# 2026-08-17 when the Nabu vanished from Home Assistant while the hardware
# sat on the network answering. A config-entry reload could not rebuild
# the dead ESPHome session; restarting Home Assistant could; recover then
# released the held backlog. The DJs climb it themselves now. This is
# DISTINCT from the stall path (#712): there the link is ALIVE and a
# restart severs a live stream mid-clip — here the entity is unavailable,
# nothing is streaming, and a restart severs nothing.
# The Voice PE's address. This WAS a frozen literal, and freezing it is
# what eventually took the station off the air (#973).
#
# The note that used to live here said HA's esphome config entry gave
# 10.89.1.161, verified 2026-08-17, and warned that .205 was a different
# device that also pings. On 2026-08-20 the station was silent for hours
# with "selected satellite is unavailable", and the wire told a different
# story: .161 answered nothing and had no ARP entry at all, while .205
# answered with MAC b4:0e:cf:2a:89:5f — which is SATELLITE_MAC, the
# station's own device. DHCP had moved it.
#
# The damage was not the wrong address; it was what the wrong address
# MEANT. _wire_probe returning "dark" is the switch that separates
# "session wedged, escalate" from "the operator turned the box off,
# stand down" — so every rung of the self-healing ladder concluded the
# box had been switched off deliberately and stood down. The station sat
# there declining to fix itself, correctly, on a false premise.
#
# So the probe asks the wire about EVERY address the device might be at,
# best first, and an answer from any of them is the device being alive.
# The env var still wins when set, because an operator naming an address
# is better evidence than anything guessed.
NABU_PROBE_HOST = os.getenv("NABU_PROBE_HOST", "10.89.1.161")


def nabu_probe_hosts() -> list[str]:
    """#973: every address worth asking, best evidence first.

    SATELLITE_HOST is whatever Home Assistant currently believes, which
    is the closest thing to authority there is — it is the address HA is
    actually trying to talk to. It is consulted lazily rather than at
    import time because it is defined far below this point in the file."""
    out: list[str] = []
    for candidate in (os.getenv("NABU_PROBE_HOST", "").strip(),
                      str(globals().get("SATELLITE_HOST") or "").strip(),
                      NABU_PROBE_HOST):
        one = str(candidate or "").strip()
        # An HA host may carry a port or a scheme; the wire wants neither.
        if "://" in one:
            one = one.split("://", 1)[1]
        one = one.split("/", 1)[0].split(":", 1)[0].strip()
        if one and one not in out:
            out.append(one)
    return out
NABU_LINK_ESCALATION = os.getenv(
    "NABU_LINK_ESCALATION", "1").lower() in ("1", "true", "yes", "on")
REPAIR_STAMPS_PATH = data_path("repair_stamps.json")


def _repair_stamps() -> dict[str, Any]:
    try:
        return json.loads(REPAIR_STAMPS_PATH.read_text())
    except Exception:
        return {}


def _repair_stamp(kind: str) -> None:
    stamps = _repair_stamps()
    row = [t for t in (stamps.get(kind) or []) if time.time() - t < 86400]
    row.append(time.time())
    stamps[kind] = row[-10:]
    try:
        REPAIR_STAMPS_PATH.write_text(json.dumps(stamps))
    except Exception:
        pass


def _repair_allowed(kind: str, cooldown: float, per_day: int) -> bool:
    """Restart budgets survive agent restarts. The in-memory guards do not
    — an agent that restarts ITSELF as a repair step forgets it just
    fired, and a wedge that persists would loop the heavy hammer."""
    row = [t for t in (_repair_stamps().get(kind) or [])
           if time.time() - t < 86400]
    if len(row) >= per_day:
        return False
    return not row or time.time() - row[-1] >= cooldown


async def nabu_device_alive() -> bool:
    """Is the hardware present on the network at all? No ping binary and
    no raw sockets in this container — but TCP already tells the truth: a
    connect OR an active refusal (RST) both prove a live IP stack at that
    address; only silence (timeout / no route) means absent. This is the
    switch that separates "session wedged, escalate" from "the operator
    turned the box off, stand down"."""
    def probe() -> bool:
        # #973: every candidate address, not one frozen literal.
        import socket as _socket
        for one in nabu_probe_hosts():
            for port in (6053, 80, 3232):
                try:
                    s = _socket.create_connection((one, port), 3)
                    s.close()
                    return True
                except ConnectionRefusedError:
                    return True
                except OSError:
                    continue
        return False
    try:
        return await asyncio.to_thread(probe)
    except Exception:  # noqa: BLE001
        return False


_NABU_LADDER_RUNNING = [False]


NABU_RESTART_BUTTON = os.getenv(
    "NABU_RESTART_BUTTON", "button.home_assistant_voice_09f8a8_restart")
_NABU_REBOOT_AT = [0.0]


async def nabu_device_restart(reason: str = "") -> bool:
    """#810: the rung between session-rebuild and paging a human — press
    the device's own restart button (the cure for the idle-but-deaf
    wedge that no software repair touches). 30-minute cooldown; the
    device drops ~20s and rejoins."""
    if time.time() - _NABU_REBOOT_AT[0] < 1800:
        return False
    token, _player = _ha_creds()
    if not token:
        return False
    _NABU_REBOOT_AT[0] = time.time()
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.post(
                f"{HA_URL}/api/services/button/press",
                headers={"Authorization": f"Bearer {token}"},
                json={"entity_id": NABU_RESTART_BUTTON})
        ok = r.status_code < 300
        pipeline_log("repair", "the watchdog pressed the Pine Box's own "
                     f"restart button ({'ok' if ok else r.status_code})"
                     + (f" — {reason}" if reason else "") + " (#810)")
        return ok
    except Exception as exc:  # noqa: BLE001
        pipeline_log("repair",
                     f"device restart press failed: {exc} (#810)")
        return False


_REPAIR_LIVE: dict[str, Any] = {"at": 0.0, "busy": False,
                                "steps": [], "verdict": ""}

# #880: what the station has LEARNED about its own faults. Each row is
# a fingerprint of the failure plus the cure that restored audio, so
# the next identical outage starts with the answer instead of the
# ladder.
REPAIR_LEARNED_PATH = data_path("repair_learned.json")
_LEARNED_LOCK = RLock()

# Seeded with what this session cost a day to discover. Each entry is
# (fingerprint, cure, why) — the fingerprint is what the tree can SEE,
# the cure is the rung that actually ended the silence.
REPAIR_SEED = [
    # #1200: the page road. Measured twice on 2026-09-11 with the station
    # reporting on and unpaused and the listener polling every second:
    # 16 clips waiting in `received`, nineteen "play() interrupted by a
    # call to pause()" and eighteen "playback stalled", and a talk gap of
    # 696s while the server went on making deliveries. A flush of the
    # feed epoch ends it; the speaker ladder cannot see it at all.
    {"fp": "page:wedged", "cure": "page_flush",
     "why": "the page holds clip after clip and starts none of them - "
            "each retry's play() is cancelled by a pause() and nothing "
            "on the page breaks the loop; the #1147 feed epoch makes it "
            "drop the queue and start clean",
     "wins": 1, "losses": 0},
    {"fp": "device:accepts|audio:none", "cure": "device_reboot",
     "why": "the Voice PE takes announces and plays nothing; only its "
            "own restart button clears it (measured three times)",
     "wins": 3, "losses": 0},
    {"fp": "engine:port_dark|process:alive", "cure": "engine_bounce",
     "why": "a wedged TTS server keeps its port bound and never "
            "answers — kill the process and redeploy, health alone "
            "never recovers it",
     "wins": 2, "losses": 0},
    {"fp": "director:dark", "cure": "lifeboat_director",
     "why": "the voice-director freezes on a blocking deploy; the "
            "lifeboat restarts it from outside docker",
     "wins": 2, "losses": 0},
    {"fp": "library:empty", "cure": "remount_shares",
     "why": "the CIFS mounts are fstab nofail and vanish on a host "
            "reboot; the docker bind is rprivate so the agent must "
            "restart after the mount",
     "wins": 2, "losses": 0},
    {"fp": "memory:cache_starved", "cure": "drop_caches",
     "why": "page cache eats the unified pool until an engine hangs "
            "mid-load with its port bound (44G cached / 23G free)",
     "wins": 1, "losses": 0},
    {"fp": "shelf:jammed|audio:none", "cure": "shed_stale_shelf",
     "why": "an unplayable head clip gags every fresh line behind it; "
            "the shelf must shed rather than preserve",
     "wins": 1, "losses": 0},
    {"fp": "routing:drifted", "cure": "restore_routing",
     "why": "a client POST wrote its stale selectors into the operator "
            "ledger and the vigil replayed it on every box flap",
     "wins": 2, "losses": 0},
    {"fp": "writer:silent", "cure": "switch_writer",
     "why": "a model that returns zero characters times out every "
            "round; swap to one benchmarked to answer",
     "wins": 1, "losses": 0},
    # #1156 (2026-09-02)
    {"fp": "device:firmware_down|device:unreachable",
     "cure": "route_around_box",
     "why": "the Voice PE's IP stack answers but no port listens: the "
            "firmware is not running and only its power cord reaches it; "
            "the show rides the app until the vigil sees the API listen",
     "wins": 1, "losses": 0},
    {"fp": "library:slow", "cure": "hot_records",
     "why": "the music share crawls over the host's Wi-Fi hop (38s for "
            "2MB measured); records are copied to local disk ahead of "
            "the needle and the picker prefers what is already there",
     "wins": 1, "losses": 0},
    {"fp": "pulse:stalled", "cure": "name_the_blocker",
     "why": "the event loop stalled on a sync call; the pulse ledger "
            "names the frame and the fix is code, not a restart",
     "wins": 0, "losses": 0},
]


def repair_learned() -> list[dict[str, Any]]:
    """The ledger, seeded the first time it is asked for."""
    with _LEARNED_LOCK:
        try:
            rows = json.loads(REPAIR_LEARNED_PATH.read_text())
            if isinstance(rows, list) and rows:
                # #1156: a seed row added AFTER the ledger existed never
                # entered it - the file only seeded when empty.
                have = {(str(r.get("fp")), str(r.get("cure")))
                        for r in rows if isinstance(r, dict)}
                added = [dict(r) for r in REPAIR_SEED
                         if (r["fp"], r["cure"]) not in have]
                if added:
                    rows.extend(added)
                    repair_learned_save(rows)
                return rows
        except Exception:  # noqa: BLE001
            pass
        rows = [dict(r) for r in REPAIR_SEED]
        repair_learned_save(rows)
        return rows


def repair_learned_save(rows: list[dict[str, Any]]) -> None:
    try:
        REPAIR_LEARNED_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = REPAIR_LEARNED_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows[:200], indent=1))
        tmp.replace(REPAIR_LEARNED_PATH)
    except OSError:
        pass


async def repair_fingerprint() -> str:
    """What is wrong, in the terms the tree can actually see. The same
    outage produces the same string, which is what makes a memory of
    cures possible at all."""
    marks: list[str] = []
    # #1200: THE PAGE IS A ROAD TOO. Every mark below describes the
    # SPEAKER, so a show routed to a page fingerprinted as healthy while
    # the page sat on clips it never started - and the ladder then
    # checked a device the show was not using.
    try:
        if page_wedge_state().get("wedged"):
            marks.append("page:wedged")
    except Exception:  # noqa: BLE001
        pass
    quiet = time.time() - _BOX_LAST_OK[0]
    if quiet > 120:
        marks.append("audio:none")
    if len(_BOX_HOLD) >= 4:
        marks.append("shelf:jammed")
    if time.time() < float(_BOX_DOWN.get("until") or 0):
        marks.append("device:breaker")
    try:
        _online = bool((await satellite_status()).get("online"))
    except Exception:  # noqa: BLE001
        _online = False
    if not _online:
        marks.append("device:unreachable")
    elif "audio:none" in marks:
        # #881: "the device answers" is only a FAULT when it answers and
        # nothing is heard. On its own it is simply a healthy speaker,
        # and fingerprinting it as a symptom had the repair reaching for
        # the reboot button at a station that was working.
        marks.append("device:accepts")
    # #1156: the shape of the silence on the wire, and the station's own
    # two new faults - a crawling library and a stalling loop.
    if not _online:
        try:
            if nabu_firmware_down(await _wire_probe_detail(NABU_PROBE_HOST)):
                marks.append("device:firmware_down")
        except Exception:  # noqa: BLE001
            pass
    try:
        if (await library_speed()).get("slow"):
            marks.append("library:slow")
    except Exception:  # noqa: BLE001
        pass
    if not pulse_report(600).get("ok"):
        marks.append("pulse:stalled")
    # Only the engine the cast actually renders on counts. Under the
    # cast lock the other one is deliberately unloaded (#866) — calling
    # that a fault would have the ledger curing the design.
    _engines = ([host_clone_engine()] if cast_engine_locked()
                else ["xtts", "f5"])
    for eng in _engines:
        try:
            if not (await engine_health(eng)).get("ready"):
                marks.append(f"engine:{eng}_dark")
        except Exception:  # noqa: BLE001
            marks.append(f"engine:{eng}_dark")
    try:
        async with httpx.AsyncClient(timeout=5) as c:
            if (await c.get(f"{VOICE_DIRECTOR_URL}/host/pressure")
                    ).status_code >= 300:
                marks.append("director:dark")
    except Exception:  # noqa: BLE001
        marks.append("director:dark")
    try:
        if not any(Path("/music/itunes").iterdir()):
            marks.append("library:empty")
    except Exception:  # noqa: BLE001
        marks.append("library:empty")
    want = _operator_routing_read()
    if str(want.get("music") or "") and \
            str(want.get("music")) != str(_RADIO.get("music_to") or ""):
        marks.append("routing:drifted")
    return "|".join(sorted(marks)) or "healthy"


def repair_suggest(fingerprint: str) -> list[dict[str, Any]]:
    """The cures that have worked for a fault like this, best first.

    Scored by wins against losses and freshness — a cure that stops
    working sinks without anyone editing a list, and a new one that
    works climbs on its own."""
    now = time.time()
    marks = set(fingerprint.split("|"))
    # #881: a fingerprint carrying no actual symptom gets no cures. The
    # ledger is for outages, not for a station that is simply running.
    if not (marks & {"audio:none", "shelf:jammed", "device:unreachable",
                     "device:breaker", "director:dark", "library:empty",
                     "routing:drifted", "memory:cache_starved",
                     "writer:silent", "device:firmware_down",
                     "library:slow", "pulse:stalled"}) and not any(
                         m.endswith("_dark") for m in marks):
        return []
    scored: list[tuple[float, dict[str, Any]]] = []
    for row in repair_learned():
        seen = set(str(row.get("fp") or "").split("|"))
        if not seen:
            continue
        overlap = len(seen & marks) / max(1, len(seen))
        if overlap < 0.5:
            continue
        wins = float(row.get("wins") or 0)
        losses = float(row.get("losses") or 0)
        rate = (wins + 1) / (wins + losses + 2)      # Laplace
        age_days = max(0.0, (now - float(row.get("at") or now)) / 86400)
        fresh = 1.0 / (1.0 + age_days / 30.0)
        scored.append((overlap * rate * (0.6 + 0.4 * fresh), row))
    scored.sort(key=lambda pair: pair[0], reverse=True)
    return [row for _s, row in scored]


def repair_record(fingerprint: str, cure: str, worked: bool,
                  why: str = "") -> None:
    """#880: remember what happened. This is the whole point — the
    station stops paying for the same lesson twice."""
    with _LEARNED_LOCK:
        rows = repair_learned()
        for row in rows:
            if str(row.get("fp")) == fingerprint and \
                    str(row.get("cure")) == cure:
                row["wins"] = int(row.get("wins") or 0) + (1 if worked else 0)
                row["losses"] = int(row.get("losses") or 0) + (
                    0 if worked else 1)
                row["at"] = time.time()
                repair_learned_save(rows)
                return
        rows.append({"fp": fingerprint, "cure": cure,
                     "why": why or "learned on air",
                     "wins": 1 if worked else 0,
                     "losses": 0 if worked else 1, "at": time.time()})
        repair_learned_save(rows)


# #1200: how long the room may be quiet, with clips waiting on the page
# and the owner still polling, before that is a wedge rather than a lull.
PAGE_WEDGE_QUIET = 150.0
PAGE_WEDGE_WAITING = 4
_PAGE_WEDGE_AT = [0.0]
PAGE_WEDGE_REST = 180.0


def page_wedge_state() -> dict[str, Any]:
    """#1200: is the page holding clips it never starts?

    Three things at once, because each alone is ordinary: clips waiting
    in `received`, the stall/interrupt error pair that marks the retry
    loop, and a room quiet longer than PAGE_WEDGE_QUIET while the listener
    that owns the air is still polling. A page that has gone away is not
    wedged - it is gone, and #1008's lease already handles that."""
    out: dict[str, Any] = {"wedged": False, "waiting": 0, "quiet": 0.0,
                           "stalls": 0, "owner": "", "why": "",
                           "paused": False}
    try:
        # #1211: IS THE DOOR SIMPLY CLOSED? Asked during a six-hour pause
        # this said "the broadcast is stuck, nothing heard for 21644
        # seconds" - every number true and the conclusion wrong, sending
        # the operator to a troubleshooting console when the cure was
        # "press play". A paused station is the one state where none of
        # the evidence below means anything.
        if radio_paused():
            out["paused"] = True
            out["why"] = ("the station is PAUSED - you took it off air "
                          "%.1f hour(s) ago and nothing has resumed it. "
                          "The booth kept working: %ds of speech is "
                          "banked and waiting."
                          % (radio_paused_for() / 3600.0,
                             int(prepared_seconds())))
            return out
        out["owner"] = owner = audio_owner()
        rows = list(_PAGE_DELIVERIES.values())
        out["waiting"] = waiting = sum(
            1 for r in rows if str(r.get("state") or "") == "received")
        now = time.time()
        stalls = 0
        for ev in list(_PAGE_ACK_EVENTS[-80:]):
            err = str(ev.get("error") or "")
            if "stalled" in err or "interrupted by a call to pause" in err:
                stalls += 1
        out["stalls"] = stalls
        # #1202: THE ROOM IS QUIET WHEN NOBODY HAS HEARD ANYTHING, not
        # when the booth has not spoken. _SPOKE_AT marks the booth
        # queueing a line; measured during the third occurrence of this
        # fault the ladder itself said "the DJs talking normally - last
        # aired line 24s ago" while fourteen clips sat unplayed and the
        # operator heard silence. The page reports its own audible volume
        # several times a clip and that is the honest clock.
        heard_at = 0.0
        for ev in list(_PAGE_ACK_EVENTS[-200:]):
            try:
                if float(ev.get("audible_volume") or 0) > 0:
                    heard_at = max(heard_at, float(ev.get("at") or 0))
            except Exception:  # noqa: BLE001
                continue
        out["heard_at"] = round(heard_at, 1)
        # #1239: the clock above needs to know somebody is out there to
        # have heard anything - "never heard" is only a fault when
        # there is somebody who would have reported it. _listeners_live
        # is the same source api_broadcast_health counts.
        try:
            if not _LISTENERS_SEEN[0] and len(_listeners_live()) > 0:
                _LISTENERS_SEEN[0] = time.time()
        except Exception:  # noqa: BLE001
            pass
        # #1231: and when the pair were last HEARD, which is a different
        # question from whether anything at all is sounding.
        out["dialogue_quiet"] = round(dialogue_quiet_for(), 1)
        # Nothing audible anywhere in the ring counts as quiet - but it
        # can only ever matter alongside the two conditions below, which
        # a freshly started station does not meet.
        quiet = (now - heard_at) if heard_at else PAGE_WEDGE_QUIET * 2
        out["quiet"] = round(quiet, 1)
        if not owner:
            out["why"] = "nobody holds the air"
            return out
        seen = float((_LISTENER_SEEN.get(owner) or {}).get("at") or 0)
        # #1208: A PAGE THAT HOLDS THE AIR AND ANSWERS NOBODY IS THE
        # WEDGE, not a reason to say there isn't one. Measured live:
        # 55 clips waiting, 32 stall reports, nothing heard for 139s -
        # and this line answered "not wedged" because the page holding
        # the exclusive had gone quiet, which gags every other player in
        # the house. The cure is different (release before flush), so it
        # is named rather than folded in.
        if now - seen > 30:
            out["gagged"] = True
            if waiting >= PAGE_WEDGE_WAITING:
                out["wedged"] = True
                out["why"] = ("the page holding the air stopped polling "
                              "%ds ago with %d clip(s) waiting - every "
                              "other player in the house is gagged for it"
                              % (int(now - seen), waiting))
            else:
                out["why"] = ("the page that holds the air stopped polling, "
                              "but only %d clip(s) are waiting" % waiting)
            return out
        if waiting < PAGE_WEDGE_WAITING:
            out["why"] = "only %d clip(s) waiting" % waiting
            return out
        if not stalls:
            out["why"] = "no stall or interrupt reported"
            return out
        if quiet < PAGE_WEDGE_QUIET:
            out["why"] = "the room has only been quiet %ds" % int(quiet)
            return out
        out["wedged"] = True
        out["why"] = ("%d clip(s) waiting on a page that is still polling, "
                      "%d stall/interrupt report(s), and nothing has "
                      "sounded for %ds" % (waiting, stalls, int(quiet)))
    except Exception as exc:  # noqa: BLE001
        out["why"] = "could not tell: %s" % type(exc).__name__
    return out


async def page_wedge_clear(force: bool = False) -> dict[str, Any]:
    """#1200: unstick a page that is holding clips it never starts.

    Cheapest first. The feed epoch (#1147) makes every page flush its
    queue and orphan the play promises still in flight; if the room is
    still quiet after that, the exclusive itself is released, because a
    gagged page is a page that has not wedged and #738's rule applies -
    heard in the wrong room beats not heard at all."""
    state = page_wedge_state()
    if not (state["wedged"] or force):
        return {"ran": False, "state": state,
                "say": "the page is not wedged: " + str(state["why"])}
    now = time.time()
    if not force and now - _PAGE_WEDGE_AT[0] < PAGE_WEDGE_REST:
        return {"ran": False, "state": state,
                "say": "a flush ran %ds ago - giving it time"
                       % int(now - _PAGE_WEDGE_AT[0])}
    _PAGE_WEDGE_AT[0] = now
    did: list[str] = []
    try:
        _RADIO["voice_cut_ms"] = int(time.time() * 1000)
        _PAGE_AIR_UNTIL[0] = 0.0
        did.append("flushed the page feed (#1147)")
        pipeline_log("air", "the page was holding %d clip(s) it never "
                     "started - the feed epoch was advanced so it drops "
                     "them and starts clean (#1200)" % state["waiting"])
    except Exception:  # noqa: BLE001
        pass
    await asyncio.sleep(12)
    again = page_wedge_state()
    if again["wedged"]:
        try:
            _AUDIO_OWNER.clear()
            did.append("released the exclusive so every page may play")
            pipeline_log("air", "the page holding the air stayed wedged "
                         "through the flush - the exclusive is released "
                         "so any other page in the house can sound "
                         "(#738/#1200)")
        except Exception:  # noqa: BLE001
            pass
    repair_note("the page player was holding clips it never started - "
                + "; ".join(did))
    return {"ran": True, "did": did, "state": state, "after": again,
            "say": "; ".join(did) or "nothing to do"}


async def _run_cure(cure: str) -> bool:
    """#881: perform one remembered cure. Returns whether it ran — not
    whether it worked; the verified-audio check afterwards decides that."""
    try:
        if cure == "device_reboot":
            _NABU_REBOOT_AT[0] = 0.0
            return await nabu_device_restart("learned cure (#881)")
        if cure == "engine_bounce":
            want = host_clone_engine()
            await _director_post(f"/director/engine/{want}/terminate")
            await asyncio.sleep(2)
            if want == "xtts":
                _XTTS_REVIVE_AT[0] = 0.0
                _xtts_revive_maybe()
            else:
                _F5_REVIVE_AT[0] = 0.0
                await _director_post("/director/engine/f5/deploy")
            return True
        if cure == "page_flush":
            got = await page_wedge_clear(force=True)          # #1200
            return bool(got.get("ran"))
        if cure == "lifeboat_director":
            return await _lifeboat_restart("voice-director")
        if cure == "restore_routing":
            want = _operator_routing_read()
            moved = False
            for key, axis in (("music", "music_to"), ("voice", "voice_to"),
                              ("reply", "reply_to")):
                pick = str(want.get(key) or "")
                if pick and pick != str(_RADIO.get(axis) or ""):
                    _RADIO[axis] = pick
                    moved = True
            if moved:
                _routing_save()
                fire_and_forget(box_route_wake())
            return moved
        if cure == "shed_stale_shelf":
            before = len(_BOX_HOLD)
            _hold_trim()
            _box_hold_save()
            fire_and_forget(_box_hold_drain_soon())
            return len(_BOX_HOLD) < before or before > 0
        if cure == "music_kick":
            # #840: right medicine for a zombie or dead stream, exactly
            # wrong over a healthy record — that is the station changing
            # the song under the listener. Asked before the stop, so a
            # refusal never leaves the air stopped with nothing behind it.
            if not track_may_cut("the remembered music_kick cure"):
                return False
            try:
                await music_box_stop_now()
            except Exception:  # noqa: BLE001
                pass
            _RADIO["fast_skip"] = True
            dj_skip()
            return True
        if cure == "piper_restart":
            return await _lifeboat_restart("wyoming-piper")
        if cure == "route_around_box":
            got = await _route_around_box("the remembered cure (#1156)")
            fire_and_forget(_box_vigil())
            _page_operator_power_cycle()
            return bool(got.get("moved")) or bool(_FAILOVER)
        if cure == "hot_records":
            _records_warm_now("the remembered cure (#1156)")
            return True
        if cure == "name_the_blocker":
            _pr = pulse_report(600)
            pipeline_log("repair", "the loop's blockers, named: "
                         + ("; ".join(
                             f"{t['frame']} {t['n']}x worst "
                             f"{float(t['worst']):.1f}s"
                             for t in (_pr.get("top") or [])[:4])
                            or "none in the last 10 min")
                         + " — that is a code fix, not a restart (#1156)")
            return False
        if cure in ("drop_caches", "remount_shares", "switch_writer"):
            # These need root on the host or an operator decision; the
            # station says so plainly rather than pretending it acted.
            pipeline_log("repair", f"the ledger says {cure!r} is what "
                         "cures this, and it needs a hand on the host "
                         "— see the triage popup (#881)")
            return False
    except Exception:  # noqa: BLE001
        return False
    return False


async def _deep_repair(reason: str = "") -> dict[str, Any]:
    """#836: the ONE BUTTON. The triage tree first; then the rung the
    tree cannot see — a device whose entities all answer while the
    speaker itself is deaf (the post-reboot ESPHome half-session that
    silenced the station on 2026-08-19: media player "playing" with no
    content, play_media accepted and ignored) — ending with a fresh
    record pushed onto a fresh device session and an audible check."""
    if _REPAIR_LIVE["busy"]:
        return {"busy": True}
    _REPAIR_LIVE.update({"at": time.time(), "busy": True,
                         "steps": [], "verdict": "working…"})

    def mark(name: str, finding: str, did: str = "") -> None:
        _REPAIR_LIVE["steps"].append(
            {"name": name, "finding": finding, "did": did})
        pipeline_log("repair", f"deep repair: {name} — {finding}"
                     + (f" → {did}" if did else "") + " (#836)")

    try:
        # #881: WHAT DOES THE STATION ALREADY KNOW? Fingerprint the
        # fault, ask the ledger which cure has ended this before, and
        # try that first — the ladder is what you climb when you have
        # no memory, not what you climb every time.
        fp = await repair_fingerprint()
        _REPAIR_LIVE["fingerprint"] = fp
        # #1200: if the page is holding clips it never started, that is
        # the fault and it costs a flush to end. Done before the speaker
        # ladder because the speaker is usually not even in the path.
        if "page:wedged" in fp:
            got = await page_wedge_clear()
            mark("the page player", "it was holding clips it never started",
                 str(got.get("say") or "")[:160])
        if fp != "healthy":
            for row in repair_suggest(fp)[:3]:
                cure = str(row.get("cure") or "")
                mark("what I remember",
                     f"this looks like {fp} — {cure} has worked "
                     f"{int(row.get('wins') or 0)}x here",
                     str(row.get("why") or "")[:120])
                if not await _run_cure(cure):
                    continue
                await asyncio.sleep(12)
                healed = time.time() - _BOX_LAST_OK[0] < 90
                # #1156: routing around a dead box is judged by the road
                # it opened, not by a speaker that cannot answer.
                if cure == "route_around_box":
                    healed = ((_RADIO.get("voice_to") or "box")
                              in ("both", "here"))
                elif cure == "hot_records":
                    healed = bool(music_hot_file(
                        _RADIO.get("coming") or _RADIO.get("now") or {}))
                repair_record(fp, cure, healed)
                mark("the remembered cure",
                     "it worked — audio is verified again" if healed
                     else "it did not settle it; climbing the tree",
                     cure)
                if healed:
                    _REPAIR_LIVE["verdict"] = (
                        ("the Nabu's firmware is not running — the show "
                         "rides the app/page until its power is pulled; "
                         "the vigil brings the routing home when the API "
                         "listens again (#1156)")
                        if cure == "route_around_box" else
                        f"fixed from memory — {cure} (the station has "
                        f"seen {fp} before)")
                    return dict(_REPAIR_LIVE)
        got = await box_triage(fix=True)
        _REPAIR_LIVE["steps"].extend(list(got.get("steps") or []))
        # #839: THE ROUTING RUNG — 2026-08-19's "atrocious" silence was
        # music routed to the PAGE while every ear was on the box. The
        # repair restores the OPERATOR's stamped routing; and if that
        # ledger itself points music away from the box, it says so
        # plainly instead of pretending the device is broken.
        want = _operator_routing_read()
        changed = []
        # #855: the ledger is keyed "music"/"voice"/"reply" — this used
        # to look up "music_to" and so never matched, never restored and
        # never warned. Dead code guarding the very thing that broke.
        for _key, axis in (("music", "music_to"), ("voice", "voice_to"),
                           ("reply", "reply_to")):
            pick = str(want.get(_key) or want.get(axis) or "")
            if pick and pick != str(_RADIO.get(axis) or ""):
                _RADIO[axis] = pick
                changed.append(f"{_key}→{pick}")
        if changed:
            _routing_save()
            fire_and_forget(box_route_wake())
            mark("the routing", "drifted off the operator's own picks",
                 "restored: " + ", ".join(changed))
        if (_RADIO.get("music_to") or "here") not in ("box", "both"):
            mark("the routing",
                 "music is routed to the PAGE by the stamped operator "
                 "choice — the box carries voice only; flip the music "
                 "switch to Nabu if that is not what you want")
        # #841: THE DJ RUNG — "what happened to the djs": music can
        # roll while the TALK chain is dead (writer model down, engines
        # cold, a beheaded round). Measure the last AIRED line, check
        # the writer, cut to a fresh round, and put a live voice on the
        # air as proof.
        _now = time.time()
        _aired = [ln for ln in (_RADIO.get("chat") or [])
                  if ln.get("who") in ("dj", "cohost", "third", "host")
                  and ln.get("aired") not in ("held",)]
        _last_talk = float(_aired[-1].get("ts") or 0) if _aired else 0.0
        _talk_gap = _now - _last_talk if _last_talk else 1e9
        _writer_ok = False
        try:
            async with httpx.AsyncClient(timeout=6) as _c:
                _writer_ok = (await _c.get(
                    "http://127.0.0.1:11434/api/tags")).status_code == 200
        except Exception:  # noqa: BLE001
            _writer_ok = False
        if not _writer_ok:
            mark("the writer", "ollama is NOT answering — nobody can "
                 "write a round",
                 "asking the lifeboat to restart it (best effort)")
            await _lifeboat_restart("ollama")
        if _talk_gap > 600:
            mark("the DJs", "no host line has AIRED in "
                 f"{int(_talk_gap // 60)} minutes",
                 "cutting to a fresh round and putting a live line "
                 "out as proof")
            _TALK_CUT[0] += 1
            # #840: cut the ROUND, never the record. The round is dead —
            # _TALK_CUT above abandons it — but a quiet desk over a
            # perfectly good record is fixed by the proof line below,
            # which speaks over the top of it. Changing the song was
            # never part of the cure.
            if track_may_cut("the deep repair's DJ rung"):
                _RADIO["fast_skip"] = True
                dj_skip()
            else:
                mark("the record", "mid-play — left turning; the fresh "
                     "round comes over the top of it (#840)")
        if _talk_gap > 180:
            async def _prove() -> None:
                try:
                    await dj_speak(
                        "interject", _RADIO.get("now"),
                        extra=("one short line proving the desk is "
                               "alive: the DJs are back on the air "
                               "and the repair just ran"),
                        who="dj", by_hand=True)
                except Exception:  # noqa: BLE001
                    pass
            fire_and_forget(_prove())
            if _talk_gap <= 600:
                mark("the DJs", f"last aired line {int(_talk_gap)}s "
                     "ago — a proof line goes out now")
        else:
            mark("the DJs", "talking normally — last aired line "
                 f"{int(_talk_gap)}s ago")
        quiet = time.time() - _BOX_LAST_OK[0]
        routed = ((_RADIO.get("music_to") or "here") in ("box", "both")
                  or (_RADIO.get("voice_to") or "box") in ("box", "both"))
        _fw_down = (nabu_firmware_down(_WIRE_LAST)
                    if time.time() - float(_WIRE_LAST.get("at") or 0) < 300
                    else False)
        if _fw_down:
            mark("the device", "its firmware is not running (every port "
                 "refuses) — the restart button cannot reach it and a "
                 "fresh needle would play to nobody; the show rides the "
                 "app until its power is pulled (#1156)")
        elif _RADIO.get("on") and routed and box_talk_ok() and quiet > 120:
            mark("the deaf-device rung",
                 f"nothing VERIFIED audible for {int(quiet)}s — after a "
                 "reboot the entities can all answer while the speaker "
                 "is deaf",
                 "stopping any zombie stream and pressing the device's "
                 "own restart button")
            try:
                await music_box_stop_now()
            except Exception:  # noqa: BLE001
                pass
            _NABU_REBOOT_AT[0] = 0.0    # the button outranks the cooldown
            await nabu_device_restart(reason or "deep repair (#836)")
            back = False
            for _ in range(10):
                await asyncio.sleep(6)
                _SAT_ALIVE.update({"checked": 0.0, "entity": ""})
                if bool((await satellite_status()).get("online")):
                    back = True
                    break
            mark("the device", "rejoined after its reboot" if back
                 else "did NOT rejoin within a minute — that is a power "
                 "cord, not software", "")
            _RADIO["fast_skip"] = True
            # #840 EXEMPT: the device was just power-cycled and nothing
            # has VERIFIED audible for two minutes — whatever the record
            # clock believes, none of it is reaching the room. The fresh
            # session needs a record pushed onto it or the box stays
            # silent until the old record's clock runs out.
            dj_skip()
            mark("the fresh needle",
                 "a new record pushed onto the fresh session")
            drained = 0
            while _BOX_HOLD and drained < 6:
                if not await box_hold_drain_one():
                    break
                drained += 1
            if drained:
                mark("the backlog", f"{drained} held clip(s) replayed")
        for _ in range(12):
            if time.time() - _BOX_LAST_OK[0] < 90:
                break
            await asyncio.sleep(5)
        fresh = time.time() - _BOX_LAST_OK[0]
        if fresh < 120:
            _REPAIR_LIVE["verdict"] = (
                "ON AIR and VERIFIED AUDIBLE — the speaker carried "
                f"sound {int(fresh)}s ago")
        elif _fw_down:
            _REPAIR_LIVE["verdict"] = (
                "the Nabu's firmware is not running — pull its power for "
                "ten seconds; the show rides the app meanwhile and the "
                "routing comes home on its own (#1156)")
        else:
            _REPAIR_LIVE["verdict"] = (
                "everything restartable was restarted, but no playout "
                "has verified yet — if the speaker is still quiet, "
                "check its power and volume; the show keeps knocking "
                "on its own")
        mark("the verdict", _REPAIR_LIVE["verdict"])
        # #881: the ladder teaches as well. Whatever the tree did, the
        # outcome is attached to this fingerprint so the next identical
        # fault starts nearer the answer.
        try:
            _fp = str(_REPAIR_LIVE.get("fingerprint") or "")
            if _fp and _fp != "healthy":
                _did = [s for s in (_REPAIR_LIVE.get("steps") or [])
                        if s.get("did")]
                _worked = time.time() - _BOX_LAST_OK[0] < 120
                for _s in _did[-2:]:
                    repair_record(_fp, str(_s.get("name") or "the tree"),
                                  _worked, str(_s.get("did") or "")[:120])
        except Exception:  # noqa: BLE001
            pass
        return dict(_REPAIR_LIVE)
    finally:
        _REPAIR_LIVE["busy"] = False



# --- #1156: THE STATION'S OWN PULSE ------------------------------------
# The host watchdog restarts this process when /healthz goes deaf for
# three probes, and every restart is three to four minutes of silence
# (2026-09-02: seven restarts in one night). Until now nothing in the
# process could say WHAT it was doing while it was deaf - py-spy over
# SSH was the only witness. A heartbeat task stamps the clock twice a
# second; a daemon thread watches the stamp, and the moment the loop is
# more than a beat and a half late it reads the main thread's frames and
# keeps the app.py names: the blocker, named, in a ledger, in the census,
# in the diagnosis, and in the DJs' mouths when someone asks how the
# station is doing.
_PULSE: dict[str, Any] = {"at": 0.0, "main_tid": 0, "loop": None,
                          "stalls": [], "by_frame": {}, "worst": 0.0,
                          "last": None, "open": None}
_PULSE_LOCK = RLock()
PULSE_STALL_S = float(os.getenv("PULSE_STALL_S", "1.5"))
PULSE_LEDGER_PATH = data_path("loop_stalls.json")
PULSE_KEEP = 120


def _pulse_frames() -> list[str]:
    """The main thread's app.py frames, innermost first."""
    import sys as _sys
    tid = int(_PULSE.get("main_tid") or 0)
    frame = _sys._current_frames().get(tid)          # noqa: SLF001
    out: list[str] = []
    while frame is not None and len(out) < 8:
        code = frame.f_code
        if code.co_filename.endswith("app.py"):
            out.append(f"{code.co_name} (app.py:{frame.f_lineno})")
        frame = frame.f_back
    return out


def _pulse_watch() -> None:
    """The daemon thread. It only ever READS the loop's world."""
    while True:
        time.sleep(0.5)
        try:
            at = float(_PULSE.get("at") or 0)
            if not at:
                continue
            late = time.time() - at
            open_stall = _PULSE.get("open")
            if late > PULSE_STALL_S:
                frames = _pulse_frames()
                if open_stall is None:
                    open_stall = {"at": at, "seen": [], "seconds": 0.0}
                    _PULSE["open"] = open_stall
                if frames and frames not in open_stall["seen"][-3:]:
                    open_stall["seen"].append(frames)
                    del open_stall["seen"][:-6]
                open_stall["seconds"] = round(late, 2)
                continue
            if open_stall is None:
                continue
            _PULSE["open"] = None
            secs = float(open_stall.get("seconds") or 0)
            seen = [fr for fr in (open_stall.get("seen") or []) if fr]
            top = seen[0][0] if seen else ""
            row = {"at": float(open_stall.get("at") or 0),
                   "seconds": secs, "top": top,
                   "frames": (seen[0] if seen else [])[:8],
                   "samples": len(seen)}
            with _PULSE_LOCK:
                stalls = _PULSE.setdefault("stalls", [])
                stalls.append(row)
                del stalls[:-PULSE_KEEP]
                by = _PULSE.setdefault("by_frame", {})
                key = (top.split(" (")[0] if top else "outside app.py")
                agg = by.setdefault(key, {"n": 0, "seconds": 0.0,
                                          "worst": 0.0, "at": 0.0})
                agg["n"] += 1
                agg["seconds"] = round(float(agg["seconds"]) + secs, 2)
                agg["worst"] = max(float(agg["worst"]), secs)
                agg["at"] = row["at"]
                _PULSE["worst"] = max(float(_PULSE.get("worst") or 0), secs)
                _PULSE["last"] = row
                snapshot = {"stalls": list(stalls), "by_frame": dict(by)}
            try:
                PULSE_LEDGER_PATH.parent.mkdir(parents=True, exist_ok=True)
                tmp = PULSE_LEDGER_PATH.with_suffix(".tmp")
                tmp.write_text(json.dumps(snapshot, indent=1))
                tmp.replace(PULSE_LEDGER_PATH)
            except Exception:  # noqa: BLE001
                pass
            if secs >= 3.0:
                loop = _PULSE.get("loop")
                if loop is not None:
                    try:
                        loop.call_soon_threadsafe(
                            pipeline_log, "pulse",
                            f"the loop stalled {secs:.1f}s in "
                            f"{top or 'a frame outside app.py'} (#1156)",
                            "\n".join(row["frames"]))
                    except Exception:  # noqa: BLE001
                        pass
        except Exception:  # noqa: BLE001
            continue


async def _pulse_beat() -> None:
    import threading as _threading
    _PULSE["main_tid"] = _threading.get_ident()
    _PULSE["loop"] = asyncio.get_running_loop()
    _PULSE["at"] = time.time()
    Thread(target=_pulse_watch, name="pulse-watch", daemon=True).start()
    while True:
        _PULSE["at"] = time.time()
        await asyncio.sleep(0.5)


@app.on_event("startup")
async def _startup_pulse() -> None:
    fire_and_forget(_pulse_beat())


def pulse_report(window: float = 600.0) -> dict[str, Any]:
    """What the loop has been stuck in lately, worst first. `ok` is
    false once a stall reached the host watchdog's own probe timeout."""
    now = time.time()
    with _PULSE_LOCK:
        recent = [r for r in (_PULSE.get("stalls") or [])
                  if now - float(r.get("at") or 0) <= window]
        by = {k: dict(v) for k, v in (_PULSE.get("by_frame") or {}).items()}
    worst = max((float(r.get("seconds") or 0) for r in recent), default=0.0)
    total = round(sum(float(r.get("seconds") or 0) for r in recent), 1)
    top = sorted(((k, v) for k, v in by.items()
                  if now - float(v.get("at") or 0) <= window),
                 key=lambda kv: -float(kv[1].get("seconds") or 0))[:6]
    open_stall = _PULSE.get("open")
    ok = worst < 8.0
    if not recent and not open_stall:
        reading = (f"steady - no stall over {PULSE_STALL_S:g}s in the last "
                   f"{int(window // 60)} min")
    else:
        lead = top[0] if top else None
        reading = (f"{len(recent)} stall(s) in the last {int(window // 60)} "
                   f"min, worst {worst:.1f}s"
                   + (f" - mostly {lead[0]} ({lead[1].get('n')}x, "
                      f"{float(lead[1].get('seconds') or 0):.1f}s)" if lead
                      else "")
                   + (f"; stalling NOW for "
                      f"{float(open_stall.get('seconds') or 0):.1f}s"
                      if open_stall else ""))
        if not ok:
            reading += (" - past the host watchdog's 8s probe; this is "
                        "what restarts the station")
    return {"window_s": window, "stalls": len(recent),
            "worst_s": round(worst, 2), "stalled_s": total,
            "recent": recent[-12:],
            "top": [{"frame": k, **v} for k, v in top],
            "stalling_now": (dict(open_stall) if open_stall else None),
            "ok": ok, "reading": reading}


# --- #1156: THE LIBRARY ROAD -------------------------------------------
# The music library is a CIFS share on exbox, reached over the host's
# Wi-Fi hop. 2026-09-02 it measured 38s for 2MB and 28s for a stat - a
# record could not stream from it on ANY speaker, and every sync touch
# of it on the loop was a deaf window. The road now: records are copied
# onto local disk ahead of the needle (the hot shelf), /music serves the
# local copy when there is one, the speed of the share is measured and
# reported, and when it crawls the picker prefers what is already here.
MUSIC_HOT_DIR = data_path("music_hot")
MUSIC_HOT_KEEP = int(os.getenv("MUSIC_HOT_KEEP", "40"))
LIBRARY_SLOW_KBPS = float(os.getenv("LIBRARY_SLOW_KBPS", "300"))
_HOT_JOBS: set[str] = set()
_HOT_LOCK = RLock()
_HOT_GATE = BoundedSemaphore(1)
_LIBRARY: dict[str, Any] = {"at": 0.0, "kbps": 0.0, "probe_s": 0.0,
                            "slow": False, "reading": "not measured yet",
                            "path": ""}


def _music_hot_path(track: dict[str, Any]) -> Path:
    return MUSIC_HOT_DIR / f"{track.get('id')}{track.get('ext') or ''}"


def music_hot_file(track: dict[str, Any] | None) -> Path | None:
    """The local copy of this record, or None. Local disk - cheap."""
    try:
        if not track or not track.get("id") or track.get("tape"):
            return None
        p = _music_hot_path(track)
        return p if p.is_file() and p.stat().st_size > 0 else None
    except Exception:  # noqa: BLE001
        return None


def _library_note_speed(nbytes: int, seconds: float, src: str = "") -> None:
    kbps = (nbytes / 1024.0) / max(seconds, 0.001)
    slow = kbps < LIBRARY_SLOW_KBPS
    _LIBRARY.update({
        "at": time.time(), "kbps": round(kbps, 1),
        "probe_s": round(seconds, 2), "slow": slow,
        "path": src or _LIBRARY.get("path") or "",
        "reading": (f"crawling - {kbps:.0f} KB/s off the share "
                    f"({nbytes >> 10} KB in {seconds:.1f}s); records play "
                    "from the local shelf" if slow else
                    f"{kbps:.0f} KB/s off the share ({seconds:.2f}s for "
                    f"{nbytes >> 10} KB)")})


def library_reading(max_age: float = 180.0) -> dict[str, Any]:
    """The last reading, never a wait: stale readings kick a fresh probe
    off-loop and say so. The diagnose and the census both poll."""
    out = dict(_LIBRARY)
    age = time.time() - float(out.get("at") or 0)
    out["age_s"] = round(age) if out.get("at") else None
    if age > max_age:
        out["measuring"] = True
        try:
            fire_and_forget(library_speed())
        except Exception:  # noqa: BLE001
            pass
        if not out.get("at"):
            out["reading"] = "measuring the share now"
    return out


def _music_hot_sweep() -> None:
    """Keep the newest MUSIC_HOT_KEEP records; never the ones on air."""
    try:
        keep_ids = {str((_RADIO.get(k) or {}).get("id") or "")
                    for k in ("now", "coming")}
        files = [p for p in MUSIC_HOT_DIR.iterdir() if p.is_file()]
        for p in files:
            if p.suffix == ".part" and time.time() - p.stat().st_mtime > 7200:
                p.unlink(missing_ok=True)
        files = [p for p in files if p.suffix != ".part"]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        for p in files[MUSIC_HOT_KEEP:]:
            if p.stem not in keep_ids:
                p.unlink(missing_ok=True)
    except Exception:  # noqa: BLE001
        pass


def _music_hot_warm(track: dict[str, Any] | None, why: str = "") -> bool:
    """Copy one record off the share onto local disk - on a thread, one
    at a time, and the copy's own timing feeds the speed reading."""
    if not track or not track.get("id") or not track.get("path") \
            or track.get("tape"):
        return False
    tid = str(track.get("id"))
    src = str(track.get("path"))
    dest = _music_hot_path(track)
    if dest.is_file():
        return False
    with _HOT_LOCK:
        if tid in _HOT_JOBS:
            return False
        _HOT_JOBS.add(tid)
    part = dest.with_name(dest.name + ".part")

    def run() -> None:
        try:
            with _HOT_GATE:
                if dest.is_file():
                    return
                MUSIC_HOT_DIR.mkdir(parents=True, exist_ok=True)
                started = time.time()
                copied = 0
                with open(src, "rb") as fin, open(part, "wb") as fout:
                    while True:
                        block = fin.read(1 << 20)
                        if not block:
                            break
                        fout.write(block)
                        copied += len(block)
                part.replace(dest)
                took = time.time() - started
                if copied:
                    _library_note_speed(copied, took, src)
                _music_hot_sweep()
        except Exception:  # noqa: BLE001
            try:
                part.unlink(missing_ok=True)
            except Exception:  # noqa: BLE001
                pass
        finally:
            with _HOT_LOCK:
                _HOT_JOBS.discard(tid)
    Thread(target=run, name=f"hot-{tid}", daemon=True).start()
    return True


def _records_warm_now(why: str = "") -> int:
    """Warm what is about to play: the up-next, the request line's head,
    and the top of the queue."""
    rows = ([_RADIO.get("coming") or {}]
            + list((_RADIO.get("requests") or [])[:2])
            + list((_RADIO.get("queue") or [])[:2]))
    n = 0
    for row in rows:
        if row and not music_hot_file(row) and _music_hot_warm(row, why):
            n += 1
    return n


def _hot_shelf_pick() -> dict[str, Any] | None:
    """A record already on the local shelf that has not aired lately."""
    try:
        recent = {str(r.get("id") or "") for r in read_played()[:40]}
        now_id = str((_RADIO.get("now") or {}).get("id") or "")
        picks = []
        for p in MUSIC_HOT_DIR.iterdir():
            if not p.is_file() or p.suffix == ".part":
                continue
            tid = p.stem
            if tid == now_id or tid in recent or tid in _TRACK_TALK:
                continue
            track = music_track(tid)
            if track:
                picks.append(track)
        return random.choice(picks) if picks else None
    except Exception:  # noqa: BLE001
        return None


def library_probe() -> dict[str, Any]:
    """Read half a megabyte off the share and time it. Thread only."""
    src = ""
    for cand in (_RADIO.get("now") or {}, _RADIO.get("coming") or {}):
        p = str(cand.get("path") or "")
        if p and not cand.get("tape"):
            src = p
            break
    if not src:
        tracks = music_index()
        if tracks:
            src = str(random.choice(tracks[:3000]).get("path") or "")
    if not src:
        return dict(_LIBRARY)
    started = time.time()
    n = 0
    try:
        with open(src, "rb") as fh:
            while n < (512 << 10):
                block = fh.read(128 << 10)
                if not block:
                    break
                n += len(block)
    except Exception as exc:  # noqa: BLE001
        _LIBRARY.update({"at": time.time(), "kbps": 0.0,
                         "probe_s": round(time.time() - started, 2),
                         "slow": True, "path": src,
                         "reading": f"the library did not answer: {exc}"[:160]})
        return dict(_LIBRARY)
    _library_note_speed(n, time.time() - started, src)
    return dict(_LIBRARY)


async def library_speed(max_age: float = 90.0) -> dict[str, Any]:
    """The share's speed, remembered for a minute and a half."""
    if time.time() - float(_LIBRARY.get("at") or 0) < max_age:
        return dict(_LIBRARY)
    try:
        return await asyncio.wait_for(asyncio.to_thread(library_probe), 25)
    except asyncio.TimeoutError:
        _LIBRARY.update({"at": time.time(), "kbps": 0.0, "probe_s": 25.0,
                         "slow": True,
                         "reading": "crawling - a 512 KB read did not finish "
                                    "in 25s; records play from the local "
                                    "shelf"})
        return dict(_LIBRARY)
    except Exception:  # noqa: BLE001
        return dict(_LIBRARY)


async def records_warmer() -> None:
    """Every half minute while the show is on: the up-next onto local
    disk, and a fresh speed reading every two minutes."""
    await asyncio.sleep(20)
    while True:
        try:
            if _RADIO.get("on"):
                _records_warm_now("the warmer")
                if time.time() - float(_LIBRARY.get("at") or 0) > 120:
                    await library_speed()
        except Exception:  # noqa: BLE001
            pass
        await asyncio.sleep(30)


@app.on_event("startup")
async def _startup_records_warmer() -> None:
    fire_and_forget(records_warmer())


DIALOGUE_QUIET_LIMIT = float(os.getenv("DIALOGUE_QUIET_LIMIT", "420"))
_DIALOGUE_FIX_AT = [0.0]


async def dialogue_watchdog() -> None:
    """#857: the cast must be HEARD, not merely scheduled.

    onair_watchdog asks whether the box has been silent; a station
    spinning records with a mute cast sails past that for ever, and
    that is the outage the operator kept reporting — music fine, DJs
    gone. This watches the one number that matters: when a host line
    was last VERIFIED audible. Seven minutes without one, while the
    show is on and pointed at the box, and the deep repair runs on its
    own — engines, director, device, shelf and all — with a twenty
    minute cooldown so a genuinely quiet stretch is never thrashed."""
    while True:
        await asyncio.sleep(60)
        try:
            if not _RADIO.get("on") or not box_talk_ok():
                continue
            # #1131: off air, nobody has said a host line ON PURPOSE. A
            # paused station always reads "quiet seven minutes", so this
            # ran the deep repair - which presses the box's restart
            # button - twice in one pause, then drove writes and renders
            # into a box that declined every one.
            if radio_paused():
                continue
            if _FAILOVER:
                continue        # #1156: routed around a dead box on purpose
            if (_RADIO.get("voice_to") or "box") not in ("box", "both"):
                continue                     # the box is not the audience
            now = time.time()
            if now - _DIALOGUE_FIX_AT[0] < 1200:
                continue
            aired = [ln for ln in (_RADIO.get("chat") or [])
                     if ln.get("who") in ("dj", "cohost", "third", "host")
                     and ln.get("aired") in ("box", "stream", "both")]
            last = float(aired[-1].get("air_at")
                         or aired[-1].get("ts") or 0) if aired else 0.0
            # A station that just started has no history to judge.
            if not last:
                continue
            quiet = now - last
            if quiet < DIALOGUE_QUIET_LIMIT:
                continue
            _DIALOGUE_FIX_AT[0] = now
            pipeline_log("repair", "no host line has been heard in "
                         f"{int(quiet // 60)} minutes while the show is "
                         "on and pointed at the box — running the deep "
                         "repair without being asked (#857)")
            note_action("🚑 the DJs went quiet — repairing on my own")
            fire_and_forget(_deep_repair("the dialogue watchdog (#857)"))
        except Exception:  # noqa: BLE001
            pass                     # a watchdog must never take the show


@app.on_event("startup")
async def _startup_dialogue_watchdog() -> None:
    fire_and_forget(dialogue_watchdog())


async def onair_watchdog() -> None:
    """#810: FM ON means AUDIBLE. When the switch says broadcasting but
    nothing verified has come out of the speaker for ten minutes, the
    station investigates itself — selfheal, then the link ladder, then
    the device's own restart button — and says so in the ledger, so the
    operator never discovers dead air before the machinery does."""
    while True:
        await asyncio.sleep(120)
        try:
            if not (_RADIO.get("on") and box_talk_ok()
                    and (_RADIO.get("voice_to") or "box") in ("box",
                                                              "both")):
                continue
            # #1131: same stand-down as the dialogue watchdog. "FM ON
            # means AUDIBLE" is the right rule for a broadcasting
            # station; a paused one is inaudible by instruction, and
            # this one's ladder ends at the device's restart button.
            if radio_paused():
                continue
            if _FAILOVER:
                continue        # #1156: routed around a dead box on purpose
            quiet = time.time() - _BOX_LAST_OK[0]
            if quiet < 600:
                continue
            pipeline_log("repair", "on-air watchdog: FM is ON but "
                         f"nothing verified has aired in "
                         f"{int(quiet / 60)} min — the station "
                         "investigates itself (#810)")
            await satellite_selfheal()
            await asyncio.sleep(90)
            if time.time() - _BOX_LAST_OK[0] < 120:
                continue                 # selfheal brought it back
            await nabu_link_ladder("on-air watchdog (#810)")
            await asyncio.sleep(120)
            if time.time() - _BOX_LAST_OK[0] < 150:
                continue                 # the ladder brought it back
            await nabu_device_restart("still silent after the ladder")
            await asyncio.sleep(120)
            if time.time() - _BOX_LAST_OK[0] < 150:
                continue
            # #814: every rung failed — the full tree classifies it,
            # routes the show around a dark device, and stands vigil.
            await box_triage()
        except Exception:  # noqa: BLE001
            pass                         # the watchdog never dies


@app.on_event("startup")
async def _startup_onair_watchdog() -> None:
    fire_and_forget(onair_watchdog())


_WIRE_LAST: dict[str, Any] = {"at": 0.0, "state": "", "host": "",
                              "ports": {}, "listening": False}
_FAILOVER: dict[str, Any] = {}
_POWER_PAGED_AT = [0.0]


async def _wire_probe_detail(host: str = "") -> dict[str, Any]:
    """#1156: the wire WITH the port shape. Three readings, not two:
    'dark' (nothing answers - power or Wi-Fi), 'alive' with the ESPHome
    API listening on 6053 (healthy), and 'alive' with every port refusing
    - the IP stack is up and the firmware is not, which is the state the
    old two-state probe called "alive" and then climbed a ladder of Home
    Assistant restarts that could never reach it (2026-09-02: four
    restarts, the whole day's budget, for nothing).

    Home Assistant's own address for the device is asked first and its
    answer is final; the other candidates only count when the API is
    OPEN on them - a stranger refusing ports at a stale address is not
    evidence of anything (the .161 trap, the other way round)."""
    def scan(one: str) -> dict[str, str]:
        import socket as _socket
        ports: dict[str, str] = {}
        for port in (6053, 80, 3232):
            try:
                c = _socket.create_connection((one, port), 3)
                c.close()
                ports[str(port)] = "open"
            except ConnectionRefusedError:
                ports[str(port)] = "refused"
            except OSError:
                ports[str(port)] = "timeout"
        return ports

    def probe() -> dict[str, Any]:
        first = str(globals().get("SATELLITE_HOST") or "").strip()
        if "://" in first:
            first = first.split("://", 1)[1]
        first = first.split("/", 1)[0].split(":", 1)[0].strip()
        order = [h for h in ([first] if first else [])
                 + ([host] if host else []) + nabu_probe_hosts() if h]
        seen: list[str] = []
        verdict: dict[str, Any] | None = None
        for one in order:
            if one in seen:
                continue
            seen.append(one)
            ports = scan(one)
            answered = any(v in ("open", "refused") for v in ports.values())
            listening = ports.get("6053") == "open"
            if listening:
                return {"state": "alive", "host": one, "ports": ports,
                        "listening": True}
            if answered and verdict is None and (one == first or not first):
                verdict = {"state": "alive", "host": one, "ports": ports,
                           "listening": False}
        return verdict or {"state": "dark", "host": "", "ports": {},
                           "listening": False}
    try:
        out = await asyncio.to_thread(probe)
    except Exception:  # noqa: BLE001
        out = {"state": "dark", "host": "", "ports": {}, "listening": False}
    out["at"] = time.time()
    _WIRE_LAST.update(out)
    return out


def nabu_firmware_down(detail: dict[str, Any] | None) -> bool:
    """Alive on the wire with nothing listening = the firmware is not
    running. No restart of Home Assistant, no press of the device's own
    button, reaches that; only its power cord does."""
    d = detail or {}
    return d.get("state") == "alive" and not d.get("listening")


def wire_reading(detail: dict[str, Any] | None) -> str:
    d = detail or {}
    if not d or not d.get("state"):
        return "not probed yet"
    if d.get("state") == "dark":
        return "dark - nothing answers on any port: power or Wi-Fi"
    if d.get("listening"):
        return f"alive at {d.get('host')} - the ESPHome API is listening"
    return (f"answers the network at {d.get('host')} but nothing is "
            "listening on it (6053/80/3232 refused): the firmware is not "
            "running - no Home Assistant restart or button press can reach "
            "it; it needs its power pulled for ten seconds")


async def _route_around_box(why: str = "") -> dict[str, Any]:
    """#1156: the show must be audible SOMEWHERE. The DJ voice rides
    'both'; and when the box was the ONLY music road, the records ride
    'both' too - remembered, so the vigil brings them home the moment
    the box's API listens again. #855 still stands for blips: this runs
    only on a confirmed hard-down, never on a flap."""
    payload: dict[str, Any] = {"system": True}
    voice_was = str(_RADIO.get("voice_to") or "box")
    music_was = str(_RADIO.get("music_to") or "here")
    if voice_was not in ("both", "here"):
        payload["voice"] = "both"
    music_moved = music_was == "box"
    if music_moved:
        payload["music"] = "both"
    if len(payload) == 1:
        return {"moved": False}
    if not _FAILOVER:
        _FAILOVER.update({"at": time.time(), "voice_was": voice_was,
                          "music_was": music_was,
                          "music_moved": music_moved, "why": why})
    try:
        _api_key = os.getenv("SPARK_AGENT_API_KEY", "")
        async with httpx.AsyncClient(timeout=10) as client:
            await client.post(
                "http://127.0.0.1:8096/api/dj/output",
                headers={"Authorization": f"Bearer {_api_key}"},
                json=payload)
    except Exception:  # noqa: BLE001
        return {"moved": False}
    try:
        _SPEAK_LAST.update({"why": "the Nabu's firmware is not running - "
                                   "the show rides the app until its "
                                   "power is pulled", "at": time.time()})
    except Exception:  # noqa: BLE001
        pass
    pipeline_log("repair", "routed the show around the box: "
                 + ", ".join(f"{k} -> {v}" for k, v in payload.items()
                             if k != "system")
                 + f" - {why} (#1156)")
    return {"moved": True, **payload}


def _page_operator_power_cycle(speak: bool = False) -> None:
    """#1156: say it ONCE, everywhere the operator looks - the action
    log, the bell, and (when asked) the air - and not again for half an
    hour."""
    if time.time() - _POWER_PAGED_AT[0] < 1800:
        return
    _POWER_PAGED_AT[0] = time.time()
    note_action("🔌 the Nabu needs a power cycle - every port refuses, "
                "its firmware is not running; pull its plug for ten "
                "seconds. The show rides the app until it rejoins")
    try:
        NOTIFICATIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
        lines: list[str] = []
        if NOTIFICATIONS_PATH.exists():
            lines = NOTIFICATIONS_PATH.read_text().splitlines()[-399:]
        lines.append(json.dumps({
            "ts": int(time.time()), "kind": "repair",
            "title": "The Nabu needs a power cycle",
            "subtitle": "Its firmware is not running (every port refuses). "
                        "Pull its plug for ten seconds; the show rides the "
                        "app meanwhile and the routing comes home on its own.",
            "ref": {"guide": "/guide/pinebox"}}))
        NOTIFICATIONS_PATH.write_text("\n".join(lines) + "\n")
    except Exception:  # noqa: BLE001
        pass
    if speak and _RADIO.get("on") and not radio_paused():
        fire_and_forget(dj_banter(None, lines=2, angle=(
            "STATION NOTICE, mid-show: the Nabu speaker is on the network "
            "but its firmware has stopped - nothing the station can press "
            "reaches it; it needs its power pulled for ten seconds. Tell "
            "the room plainly, in character, that the show is riding the "
            "app until somebody does that.")))


async def _wire_probe(host: str = "") -> str:
    """What the DEVICE ITSELF says on the wire: 'alive' (a port answered
    or refused — something is home), or 'dark' (nothing at all — power
    or Wi-Fi, and no software can reach it).

    #973: asks every address the device might be at rather than one
    frozen literal. `host` is still honoured and still tried first, so
    every existing call site behaves as it did whenever the address it
    passes is right — it simply no longer says "dark" when the box has
    only moved."""
    def probe() -> str:
        import socket as _socket
        tried: list[str] = []
        for candidate in ([host] if host else []) + nabu_probe_hosts():
            one = str(candidate or "").strip()
            if not one or one in tried:
                continue
            tried.append(one)
            for port in (6053, 80, 3232):
                try:
                    s = _socket.create_connection((one, port), 3)
                    s.close()
                    return "alive"
                except ConnectionRefusedError:
                    return "alive"
                except OSError:
                    continue
        return "dark"
    try:
        return await asyncio.to_thread(probe)
    except Exception:  # noqa: BLE001
        return "dark"


async def _wire_probe_one(host: str) -> str:
    """#973: ONE address, with no fallback to the others.

    _wire_probe deliberately tries every candidate, which is right when
    the question is "is the box reachable at all" and wrong when the
    question is "which address is it on" — asking about .161 there
    answered "alive" on the strength of .205, which is exactly the kind
    of quietly-wrong answer that caused this outage in the first place."""
    def probe() -> str:
        import socket as _socket
        one = str(host or "").strip()
        if not one:
            return "dark"
        for port in (6053, 80, 3232):
            try:
                c = _socket.create_connection((one, port), 3)
                c.close()
                return "alive"
            except ConnectionRefusedError:
                return "alive"
            except OSError:
                continue
        return "dark"
    try:
        return await asyncio.to_thread(probe)
    except Exception:  # noqa: BLE001
        return "dark"


async def nabu_wire_report() -> dict[str, Any]:
    """#973: which of the candidate addresses is actually answering.

    The outage this fixes was invisible precisely because nothing ever
    said WHICH address had been asked. Now the panel and the log can."""
    out: dict[str, Any] = {"hosts": [], "alive": "", "configured":
                           NABU_PROBE_HOST}
    for one in nabu_probe_hosts():
        state = await _wire_probe_one(one)
        out["hosts"].append({"host": one, "state": state})
        if state == "alive" and not out["alive"]:
            out["alive"] = one
    return out


_BOX_VIGIL_ON = [False]


async def _box_vigil() -> None:
    """#814: the tree's last rung - while the device is off the network,
    watch the wire once a minute; the moment the device is BACK, run the
    recovery and tell the room. The show rides the page/app meanwhile.

    #1156: "back" means the ESPHome API is LISTENING, not merely that the
    IP stack answers. A refused port used to count as a return, and the
    vigil handed the show straight back to a box whose firmware was not
    running."""
    if _BOX_VIGIL_ON[0]:
        return
    _BOX_VIGIL_ON[0] = True
    pipeline_log("repair", "vigil: watching the wire for the Pine Box "
                 "to rejoin - the show rides the page/app until it "
                 "does (#814)")
    try:
        while True:
            await asyncio.sleep(60)
            _wd = await _wire_probe_detail(NABU_PROBE_HOST)
            if _wd.get("state") != "alive":
                continue
            if not _wd.get("listening"):
                continue                 # an IP stack is not a speaker
            pipeline_log("repair", "vigil: the Pine Box's API is LISTENING "
                         "again - running recovery (#814/#1156)")
            # Give Home Assistant a minute to pick the entity back up
            # before the routing goes home, or the first lines land on
            # the shelf instead of the speaker.
            for _ in range(12):
                _SAT_ALIVE["checked"] = 0.0
                try:
                    if bool((await satellite_status()).get("online")):
                        break
                except Exception:  # noqa: BLE001
                    pass
                await asyncio.sleep(10)
            try:
                await satellite_selfheal()
            except Exception:  # noqa: BLE001
                pass
            # #818: the failover was TEMPORARY - the operator's
            # remembered routing comes back with the box. #1156: and so
            # do the records, when the failover was what moved them.
            payload: dict[str, Any] = {}
            ledger = _operator_routing_read()
            _fo = dict(_FAILOVER)
            if ledger:
                payload.update({k: v for k, v in ledger.items()
                                if k != "music"})
            elif _fo.get("voice_was"):
                payload["voice"] = _fo["voice_was"]
            if _fo.get("music_moved") and _fo.get("music_was"):
                payload["music"] = _fo["music_was"]
            _FAILOVER.clear()
            if payload:
                try:
                    _api_key = os.getenv("SPARK_AGENT_API_KEY", "")
                    async with httpx.AsyncClient(timeout=10) as client:
                        await client.post(
                            "http://127.0.0.1:8096/api/dj/output",
                            headers={"Authorization":
                                     f"Bearer {_api_key}"},
                            json={**payload, "system": True})
                    pipeline_log("repair", "vigil: routing restored - "
                                 f"{payload} (#818/#1156)")
                except Exception:  # noqa: BLE001
                    pass
            try:
                _SPEAK_LAST.update({"why": "", "at": time.time()})
            except Exception:  # noqa: BLE001
                pass
            if _RADIO.get("on"):
                fire_and_forget(dj_banter(None, lines=3, angle=(
                    "NEWS FROM THE BACK ROOM, mid-show: the box "
                    "speaker just rejoined the network after being "
                    "dark - welcome it back on air, in character, "
                    "and carry on.")))
            return
    finally:
        _BOX_VIGIL_ON[0] = False


async def box_triage(fix: bool = True) -> dict[str, Any]:
    """#814: the DJs' troubleshooting TREE. Walks the whole chain — the
    show, Home Assistant, the entity, the device on the wire — writes
    every finding to the repair ledger, ACTS on every branch when `fix`
    is on, and ends with a station somebody can hear no matter which
    piece is dead: a dark device means the show routes to the page/app
    and a vigil watches for its return."""
    steps: list[dict[str, str]] = []

    def note(name: str, finding: str, did: str = "") -> None:
        steps.append({"name": name, "finding": finding, "did": did})
        pipeline_log("repair", f"triage: {name} — {finding}"
                               + (f" → {did}" if did else "") + " (#814)")

    # 1. the show itself
    _want_on = False
    try:
        _want_on = bool(json.loads(RADIO_ON_PATH.read_text()).get("on"))
    except Exception:  # noqa: BLE001
        _want_on = False
    if _RADIO.get("on"):
        note("the show", "FM is on and the desk is running")
    elif _want_on:
        note("the show", "FM was left ON but the desk is stopped",
             "resuming it" if fix else "would resume")
        if fix:
            try:
                await resume_radio()
            except Exception:  # noqa: BLE001
                pass
    else:
        note("the show", "the operator's FM switch is OFF — that choice "
             "stands; nothing below will be audible until it is on")

    # 2. Home Assistant
    token, _pl = _ha_creds()
    ha_ok = False
    if token:
        try:
            async with httpx.AsyncClient(timeout=8) as client:
                ha_ok = (await client.get(
                    f"{HA_URL}/api/",
                    headers={"Authorization": f"Bearer {token}"}
                )).status_code < 300
        except Exception:  # noqa: BLE001
            ha_ok = False
    note("Home Assistant", "answering" if ha_ok else
         "NOT answering — the whole voice road is down",
         "" if ha_ok else ("the link ladder restarts it" if fix else ""))

    # 3. the entity
    link: dict[str, Any] = {}
    try:
        link = await satellite_status()
    except Exception:  # noqa: BLE001
        link = {}
    ent = ("available" if link.get("online") else "unavailable")
    note("the satellite entity", ent)

    # 3b (#826): the MUSIC half has its own entity — the media player.
    # A silent device with a healthy satellite was exactly this: voice
    # announces landing while every record fell into a void.
    mp_state = ""
    if token and NABU_MEDIA_PLAYER:
        try:
            async with httpx.AsyncClient(timeout=8) as client:
                _mp = await client.get(
                    f"{HA_URL}/api/states/{NABU_MEDIA_PLAYER}",
                    headers={"Authorization": f"Bearer {token}"})
                mp_state = (str(_mp.json().get("state") or "")
                            if _mp.status_code == 200 else "missing")
        except Exception:  # noqa: BLE001
            mp_state = "unreachable"
    if mp_state in ("unavailable", "unknown", "missing", "unreachable"):
        note("the music player", f"entity {mp_state} — records are "
             "routed into a void while the satellite still talks",
             "climbing the link ladder" if fix else "")
        if fix and ha_ok:
            fire_and_forget(nabu_link_ladder("music player dead (#826)"))
    elif mp_state:
        note("the music player", mp_state)

    # 3c (#837, the 2026-08-19 reboot): the music LIBRARY is a CIFS
    # mount with `nofail` — a host reboot can silently skip it, and the
    # show then queues 35k indexed tracks whose files all 404. The
    # remount needs root on the host, so the tree can only say it
    # plainly and loudly.
    try:
        _lib_ok = await asyncio.to_thread(
            lambda: any(Path("/music/itunes").iterdir()))
    except Exception:  # noqa: BLE001
        _lib_ok = False
    if not _lib_ok:
        note("the music library",
             "/music/itunes is EMPTY — the CIFS share did not survive a "
             "host reboot (nofail); every indexed track 404s",
             "needs a hand on the host: sudo mount "
             "/home/ehm_eckx/music/itunes, then restart spark-agent so "
             "the bind sees it")
    else:
        note("the music library", "mounted and populated")

    # 4. the device, on the wire — the truth no entity can fake
    wire_detail = await _wire_probe_detail(NABU_PROBE_HOST)
    wire = str(wire_detail.get("state") or "dark")
    firmware_down = nabu_firmware_down(wire_detail) and not link.get("online")
    if firmware_down:
        # #1156: the third shape. Alive on the wire, nothing listening:
        # the firmware is not running, and the ladder below (reload,
        # Home Assistant restart, the device's own button) cannot reach
        # a device whose API is not there. Route around it, stand
        # vigil for the API to LISTEN, and say plainly what it needs.
        note("the device", "answers the network but nothing is listening "
             "on it (6053/80/3232 all refused) — the firmware is not "
             "running. No Home Assistant restart or restart-button press "
             "can reach it; it needs its power pulled for ten seconds",
             "routing the show around it + standing vigil + paging the "
             "operator" if fix else "")
        if fix:
            await _route_around_box("the Nabu's firmware is down (#1156)")
            fire_and_forget(_box_vigil())
            _page_operator_power_cycle()
            repair_record("device:firmware_down|device:unreachable",
                          "route_around_box", True,
                          "the show rides the app until the API listens")
    elif wire == "alive" and not link.get("online"):
        note("the device", "alive on the wire but the entity is dead — "
             "a session wedge, not hardware",
             "climbing the link ladder" if fix else "")
        if fix and ha_ok:
            fire_and_forget(nabu_link_ladder("triage (#814)"))
    elif wire == "alive":
        _quiet = time.time() - _BOX_LAST_OK[0]
        if _quiet > 600:
            note("the device", "alive and linked but NOTHING verified in "
                 f"{int(_quiet / 60)} min — the idle-but-deaf wedge",
                 "pressing its restart button" if fix else "")
            if fix:
                await nabu_device_restart("triage — idle-but-deaf (#814)")
        else:
            note("the device", "alive, linked, and audibly delivering "
                 f"(verified {int(_quiet)}s ago)")
    else:
        note("the device", "DARK — nothing answers on any port. Power "
             "or Wi-Fi; no software can reach it",
             "routing the show around it + standing vigil"
             if fix else "")
        if fix:
            # Route AROUND: the page/app carry everything live; the
            # box shelf still holds its copy for the return.
            try:
                _api_key = os.getenv("SPARK_AGENT_API_KEY", "")
                async with httpx.AsyncClient(timeout=10) as client:
                    await client.post(
                        "http://127.0.0.1:8096/api/dj/output",
                        headers={"Authorization": f"Bearer {_api_key}"},
                        # #855: the failover moves the VOICE road,
                        # never the music road. The music switch is the
                        # operator's alone, and rerouting it on a dark
                        # blip is how records ended up playing into a
                        # browser nobody had open.
                        json={"voice": "both", "system": True})
            except Exception:  # noqa: BLE001
                pass
            fire_and_forget(_box_vigil())

    # 4b. the DIRECTOR — every engine handle routes through it
    _dir_ok = False
    try:
        async with httpx.AsyncClient(timeout=8) as client:
            _dir_ok = (await client.get(
                f"{VOICE_DIRECTOR_URL}/host/pressure")).status_code < 300
    except Exception:  # noqa: BLE001
        _dir_ok = False
    note("the voice director", "answering" if _dir_ok else
         "NOT answering — no engine can be managed",
         "" if _dir_ok else ("lifeboat restarts it" if fix else ""))
    if fix and not _dir_ok:
        await _lifeboat_restart("voice-director")
        await asyncio.sleep(6)

    # 5. the RENDER CHAIN — a healthy device is worthless if no engine
    # can make audio. The tree once declared "everything healthy" in
    # the middle of an all-engines-refused outage (#824).
    _xtts_ok = bool((await xtts_health()).get("ready"))
    _f5_ok = bool((await f5_health()).get("ready"))
    # #853: PIPER, the floor. Every ladder in the station ends here, and
    # until now nothing probed it — the rung below simply asserted
    # "NOTHING can render but Piper" without ever asking Piper. Ask it
    # for its voice list with a deadline; an open port that returns no
    # voices is the wedge, and the lifeboat has always been able to
    # restart the container.
    try:
        _piper_names = await asyncio.wait_for(piper_voices(), 8)
    except Exception:  # noqa: BLE001
        _piper_names = []
    _piper_ok = bool(_piper_names)
    note("the floor (piper)",
         f"{len(_piper_names)} voices — every ladder ends here"
         if _piper_ok else
         "NOT ANSWERING — the last resort is gone, so a line with no "
         "clone engine has nowhere left to go",
         "" if _piper_ok else
         ("restarting wyoming-piper through the lifeboat" if fix else ""))
    if fix and not _piper_ok:
        await _lifeboat_restart("wyoming-piper")
        for _ in range(6):
            await asyncio.sleep(5)
            try:
                if await asyncio.wait_for(piper_voices(), 6):
                    note("the floor (piper)", "back — the ladder has its "
                         "last rung again")
                    _piper_ok = True
                    break
            except Exception:  # noqa: BLE001
                continue
    note("the voice engines",
         f"xtts {'up' if _xtts_ok else 'DOWN'} · f5 "
         f"{'up' if _f5_ok else 'DOWN'}"
         + ("" if (_xtts_ok or _f5_ok) else
            (" — NOTHING can render but Piper" if _piper_ok else
             " — and PIPER IS DOWN TOO: nothing on this box can make "
             "audio at all")),
         "" if (_xtts_ok and _f5_ok) else
         ("redeploying the dead engine(s)" if fix else ""))
    if fix and not (_xtts_ok and _f5_ok):
        for _eng, _ok in (("xtts", _xtts_ok), ("f5", _f5_ok)):
            if not _ok:
                await _director_post(f"/director/engine/{_eng}/deploy")

    verdict = ("the station is ON AIR — " + (
        "everything is healthy" if wire == "alive" and ha_ok
        and link.get("online")
        else "riding the page/app until the Nabu is power-cycled — its "
             "firmware is not running"
        if firmware_down else "riding the page/app while the box is dark"
        if wire == "dark" else "repairs are climbing"))         if _RADIO.get("on") else "the FM switch is off"
    pipeline_log("repair", f"triage verdict: {verdict} (#814)")

    # 5. the booth is BRIEFED — the pair report the diagnosis on air,
    # in character, with the real findings in their mouths.
    if fix and _RADIO.get("on"):
        _report = "; ".join(f"{s['name']}: {s['finding']}"
                            for s in steps)
        fire_and_forget(dj_banter(None, lines=4, angle=(
            "STATION TRIAGE, LIVE: you two just ran the full "
            f"troubleshooting tree. The findings, verbatim: {_report}. "
            f"The verdict: {verdict}. Report it to the room honestly "
            "and in character — what was checked, what was found, what "
            "was done — like engineers who also happen to be on air. "
            "Do not invent findings that are not listed.")))
    return {"steps": steps, "verdict": verdict, "wire": wire,
            "firmware_down": firmware_down, "ha": ha_ok, "entity": ent}


# #844: what each engine costs to keep resident, in GB. The GB10 has
# 128G of UNIFIED memory shared by the GPU, the page cache and every
# process — so a second clone engine is not free headroom, it is half
# the pool.
ENGINE_WEIGHT_GB = {"xtts": 23.0, "f5": 24.0, "piper": 0.3,
                    "voxcpm": 8.0, "cosyvoice": 12.0, "indextts": 10.0,
                    "vibevoice": 14.0, "qwen_tts": 6.0, "kokoro": 1.0}
GPU_POOL_GB = float(os.getenv("GPU_POOL_GB", "128"))


async def gpu_load_report() -> dict[str, Any]:
    """#844: the honest cost of the current casting, plus what it would
    cost consolidated. Every seat the operator has cast is listed with
    the engine it forces resident."""
    dj = dj_settings()
    seats = [("host", "voice"), ("cohost", "cohost_voice"),
             ("third", "third_voice"), ("drop", "drop_voice"),
             ("caller", "caller_voice")]
    rows: list[dict[str, Any]] = []
    for seat, key in seats:
        v = str(dj.get(key) or "").strip()
        if not v:
            continue
        meta = voice_meta(split_engine_voice(v)[1] or v) or {}
        eng = voice_engine_for(v, seat)
        rows.append({"seat": seat, "key": key, "voice": v,
                     "name": str(meta.get("name") or v),
                     "engine": eng,
                     "gb": ENGINE_WEIGHT_GB.get(eng, 4.0)})
    engines = sorted({r["engine"] for r in rows
                      if r["engine"] in ENGINE_WEIGHT_GB})
    resident = sum(ENGINE_WEIGHT_GB.get(e, 4.0) for e in engines)
    # What ELSE is holding the pool right now.
    others: dict[str, float] = {}
    try:
        async with httpx.AsyncClient(timeout=6) as client:
            press = (await client.get(
                f"{VOICE_DIRECTOR_URL}/host/pressure")).json()
        avail = float(press.get("avail_gb") or 0)
    except Exception:  # noqa: BLE001
        avail = 0.0
    try:
        async with httpx.AsyncClient(timeout=5) as client:
            ps = (await client.get(
                "http://127.0.0.1:11434/api/ps")).json()
        for m in (ps.get("models") or []):
            others[str(m.get("name") or "a model")] = round(
                float(m.get("size") or 0) / (1 << 30), 1)
    except Exception:  # noqa: BLE001
        pass
    # The counsel.
    warn = ""
    level = "ok"
    cheapest = min(engines, key=lambda e: ENGINE_WEIGHT_GB.get(e, 4.0),
                   default="")
    if len(engines) > 1:
        level = "warn"
        saving = resident - max(
            ENGINE_WEIGHT_GB.get(e, 4.0) for e in engines)
        warn = (f"Your cast spans {len(engines)} cloning engines "
                f"({', '.join(engines)}), so ALL of them must stay "
                f"resident — about {resident:.0f}G of the {GPU_POOL_GB:.0f}G "
                f"pool. Consolidating the cast onto one engine frees "
                f"roughly {saving:.0f}G and removes the memory pressure "
                f"that wedges a loading engine (which is what silences "
                f"the DJs).")
    elif avail and avail < 30:
        level = "warn"
        warn = (f"One engine is enough for this cast, but the pool is "
                f"down to {avail:.0f}G free — the page cache or another "
                f"model is holding it. The station's UMA guard reclaims "
                f"cache every five minutes; if this persists, unload a "
                f"model you are not using.")
    else:
        warn = (f"This casting is easy on the box: one engine "
                f"({engines[0] if engines else 'none'}) covers the whole "
                f"cast, about {resident:.0f}G resident.")
    locked = cast_engine_locked()
    host_eng = host_clone_engine()
    if locked:
        # Under the lock the cast RENDERS on one engine whatever their
        # metas say, so the honest resident cost is that one engine.
        engines = [host_eng]
        resident = ENGINE_WEIGHT_GB.get(host_eng, 4.0)
        for r in rows:
            if r["seat"] in CAST_SEATS:
                r["engine"] = host_eng
                r["gb"] = ENGINE_WEIGHT_GB.get(host_eng, 4.0)
                r["follows_host"] = True
        level = "ok"
        warn = (f"The cast is unified on {host_eng} — the host's engine "
                f"is the law, about {resident:.0f}G resident, and the "
                f"lines flow without a model swap between speakers. "
                f"Heavier engines are greyed out for the cast until you "
                f"throw the master swap; callers may ride any engine.")
        if avail and avail < 25:
            level = "warn"
            warn += (f" The pool is tight though ({avail:.0f}G free) — "
                     "something else is holding memory.")
    return {"rows": rows, "engines": engines,
            "cast_engine_lock": locked, "host_engine": host_eng,
            "resident_gb": round(resident, 1),
            "pool_gb": GPU_POOL_GB, "avail_gb": avail,
            "others": others, "level": level, "advice": warn,
            "consolidate_to": engines[0] if len(engines) == 1 else (
                "xtts" if "xtts" in engines else cheapest),
            "options": [
                {"engine": e, "gb": ENGINE_WEIGHT_GB.get(e, 4.0),
                 "note": ("the cast's own engine" if e in engines
                          else "would need loading")}
                for e in ("xtts", "f5")],
            }


